const APP = "<!doctype html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover,maximum-scale=1,user-scalable=no\">\n<title>צייר המוחות – מלמדים מוח מלאכותי לזהות ציורים ומאתגרים חברים</title>\n<meta name=\"description\" content=\"צייר המוחות: משחק ציור לטלפון. מלמדים מוח מלאכותי משלכם לזהות ציורים של מילים, מפרסמים אתגרים בכיכר, ומנסים לצייר כך שהמוחות של שחקנים אחרים יזהו. ניקוד, דירוג והתראות.\">\n<link rel=\"canonical\" href=\"__ORIGIN__/\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:title\" content=\"צייר המוחות\">\n<meta property=\"og:description\" content=\"מלמדים מוח מלאכותי לזהות ציורים – ומאתגרים את המוחות של כולם.\">\n<meta property=\"og:url\" content=\"__ORIGIN__/\">\n<meta property=\"og:image\" content=\"__ORIGIN__/icon-512.png\">\n<meta property=\"og:locale\" content=\"he_IL\">\n<meta name=\"theme-color\" content=\"#FBF6EC\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-title\" content=\"צייר המוחות\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"icon\" href=\"/icon.svg\" type=\"image/svg+xml\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebApplication\",\"name\":\"צייר המוחות\",\"url\":\"__ORIGIN__/\",\"applicationCategory\":\"GameApplication\",\"operatingSystem\":\"iOS, Android\",\"inLanguage\":\"he\",\"description\":\"משחק ציור לטלפון: מלמדים מוח מלאכותי לזהות ציורים ומאתגרים את המוחות של שחקנים אחרים.\",\"offers\":{\"@type\":\"Offer\",\"price\":\"0\",\"priceCurrency\":\"ILS\"}}</script>\n<style>\n:root{\n --paper:#FBF6EC;--paper2:#F2E9D8;--sheet:#FFFDF8;--ink:#1F2440;--ink2:#565A78;--ink3:#8A8DA6;--line:#E3D7C0;\n --accent:#E2461F;--accentD:#C23A17;--accentBg:#FDE3D9;\n --l1:#1A8E58;--l1bg:#DCF2E5;--l2:#B87400;--l2bg:#FBEBC8;--l3:#6343D6;--l3bg:#E8E2FB;--l4:#1D6FA5;--l4bg:#DDEDF8;\n --ok:#1A8E58;--okBg:#DCF2E5;--bad:#CF3338;--badBg:#FBE0DF;\n --r:18px;--rs:12px;--sh:0 6px 18px -8px rgba(31,36,64,.28),0 2px 4px -2px rgba(31,36,64,.12);\n --safeB:env(safe-area-inset-bottom,0px);--safeT:env(safe-area-inset-top,0px);\n font-family:\"Fredoka\",\"Arial Hebrew\",system-ui,sans-serif;\n}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;margin:0}\nhtml,body{height:100%;background:var(--paper);color:var(--ink);overflow:hidden;overscroll-behavior:none}\nbody{font-size:16px;line-height:1.35;user-select:none;-webkit-user-select:none;\n background-image:linear-gradient(rgba(31,36,64,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(31,36,64,.045) 1px,transparent 1px);background-size:22px 22px}\n::selection{background:var(--accentBg);color:var(--ink)}\ninput{font:inherit;color:var(--ink);caret-color:var(--accent);user-select:text;-webkit-user-select:text}\nbutton{font:inherit;color:inherit;border:0;background:none;cursor:pointer;touch-action:manipulation}\nbutton:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n.ic{width:22px;height:22px;flex:none;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.num{font-variant-numeric:tabular-nums}\n.hide{display:none!important}\n\n#app{position:fixed;inset:0;display:flex;flex-direction:column;padding-top:var(--safeT);overflow:hidden}\nheader{height:56px;flex:none;display:flex;align-items:center;gap:8px;padding:0 14px}\n.logo{display:flex;align-items:center;gap:8px;flex:1;min-width:0}\n.logo svg{width:34px;height:34px;flex:none}\n.logo b{font-size:21px;font-weight:700;letter-spacing:-.01em;white-space:nowrap}\n.pill{display:flex;align-items:center;gap:6px;height:38px;padding:0 12px;border-radius:999px;background:var(--sheet);border:1.5px solid var(--line);font-weight:600;font-size:16px}\n.pill .ic{width:18px;height:18px;color:var(--l2)}\n.iconBtn{position:relative;width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:var(--sheet);border:1.5px solid var(--line)}\n.iconBtn .dot{position:absolute;top:6px;left:7px;width:10px;height:10px;border-radius:50%;background:var(--accent);border:2px solid var(--sheet)}\n.ava{font-weight:700;font-size:17px;color:#fff;background:var(--ink);border-color:var(--ink)}\n\nmain{flex:1;position:relative;min-height:0;overflow:hidden}\n.view{position:absolute;inset:0;overflow:hidden;display:none;flex-direction:column;padding:4px 16px 12px;gap:10px;min-height:0}\n.view.on{display:flex;animation:vin .22s cubic-bezier(.16,1,.3,1)}\n@keyframes vin{from{opacity:.4;transform:translateY(6px)}to{opacity:1;transform:none}}\n\nnav{flex:none;display:flex;gap:6px;padding:6px 12px calc(8px + var(--safeB));background:var(--paper);border-top:1.5px solid var(--line)}\nnav button{flex:1;height:54px;border-radius:14px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;font-size:13.5px;font-weight:600;color:var(--ink2)}\nnav button.on{background:var(--ink);color:#fff}\nnav .ic{width:24px;height:24px}\nbody.focus nav,body.focus header{display:none}\nbody.solo nav,body.solo #hScore,body.solo #hBell,body.solo #hMe,body.solo #wPub{display:none!important}\n\n/* כפתורים */\n.btn{height:52px;padding:0 20px;border-radius:16px;font-weight:600;font-size:17.5px;display:inline-flex;align-items:center;justify-content:center;gap:8px;background:var(--sheet);border:1.5px solid var(--line);transition:transform .12s,background .15s}\n.btn:active{transform:scale(.97)}\n.btn.pri{background:var(--accent);border-color:var(--accent);color:#fff;box-shadow:0 6px 14px -6px rgba(226,70,31,.7)}\n.btn.dark{background:var(--ink);border-color:var(--ink);color:#fff}\n.btn.lit{background:var(--l1);border-color:var(--l1);color:#fff}\n.btn:disabled{background:var(--paper2);border-color:var(--line);color:var(--ink3);box-shadow:none}\n.btn.sm{height:42px;font-size:15.5px;padding:0 14px;border-radius:13px}\n.tool{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:var(--sheet);border:1.5px solid var(--line);color:var(--ink2)}\n.tool.sel{background:var(--ink);color:#fff;border-color:var(--ink)}\n.row{display:flex;gap:8px;align-items:center}\n.grow{flex:1;min-width:0}\n\n/* מילים ורמות */\n.lv1{--lc:var(--l1);--lb:var(--l1bg)}.lv2{--lc:var(--l2);--lb:var(--l2bg)}.lv3{--lc:var(--l3);--lb:var(--l3bg)}.lv4{--lc:var(--l4);--lb:var(--l4bg)}\n.addErr{min-height:22px;color:var(--bad);font-size:15px;font-weight:600}\n.addBtn{margin:8px 14px;height:52px;border-radius:14px;border:2px dashed var(--l4);background:var(--l4bg);color:var(--l4);font-weight:700;font-size:17px;display:flex;align-items:center;justify-content:center;gap:8px}\n.addBtn .ic{width:22px;height:22px;flex:none}.addBtn span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.empty .addBtn{padding:0 18px}\n.tag{display:inline-flex;align-items:center;gap:5px;height:26px;padding:0 10px;border-radius:999px;background:var(--lb);color:var(--lc);font-size:13.5px;font-weight:600;white-space:nowrap}\n.tag::before{content:\"\";width:8px;height:8px;border-radius:50%;background:var(--lc)}\n\n/* החדר */\n.brainBar{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:var(--r);background:var(--sheet);border:1.5px solid var(--line);box-shadow:var(--sh)}\n.brainBar svg.mascot{width:56px;height:56px;flex:none}\n.brainBar h2{font-size:18px;font-weight:700}\n.brainBar p{font-size:14.5px;color:var(--ink2)}\n.myWordsBtn{display:flex;align-items:center;gap:10px;min-height:50px;padding:6px 14px;border-radius:15px;background:var(--sheet);border:1.5px solid var(--line);text-align:right;width:100%}\n.myWordsBtn b{font-size:17px;font-weight:700;white-space:nowrap}\n.myWordsBtn .peek{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink2);font-size:14.5px}\n.myWordsBtn .cnt{background:var(--ink);color:#fff;border-radius:999px;padding:2px 9px;font-size:14px;font-weight:600}\n.myWordsBtn:disabled{color:var(--ink2)}\n.sheet.tall{height:78%}\n.sheet .list{flex:1}\n.myWords::-webkit-scrollbar{display:none}\n.mw{flex:none;display:flex;align-items:center;gap:7px;height:44px;padding:0 13px;border-radius:14px;background:var(--lb);color:var(--ink);font-weight:600;font-size:16px;border:1.5px solid transparent}\n.mw small{font-size:13px;color:var(--lc);font-weight:600}\n.mw .flag{width:16px;height:16px;color:var(--accent)}\n.emptyLine{color:var(--ink2);font-size:14.5px;align-self:center}\n.seg{display:flex;gap:4px;padding:4px;border-radius:15px;background:var(--paper2)}\n.seg button{flex:1;height:38px;border-radius:11px;font-weight:600;font-size:15px;color:var(--ink2);display:flex;align-items:center;justify-content:center;gap:6px}\n.seg button.on{background:var(--sheet);color:var(--ink);box-shadow:0 2px 6px -2px rgba(31,36,64,.25)}\n.seg button i{width:8px;height:8px;border-radius:50%;background:var(--lc)}\n.search{display:flex;gap:8px}\n.search label{flex:1;display:flex;align-items:center;gap:8px;height:46px;padding:0 12px;border-radius:14px;background:var(--sheet);border:1.5px solid var(--line);color:var(--ink3)}\n.search input{flex:1;min-width:0;border:0;background:none;outline:none;font-size:16px}\n.search input::placeholder{color:var(--ink3)}\n.list{flex:1;min-height:0;overflow-y:auto;border-radius:var(--r);background:var(--sheet);border:1.5px solid var(--line);scrollbar-width:thin;scrollbar-color:var(--line) transparent}\n.wr{width:100%;display:flex;align-items:center;gap:10px;min-height:52px;padding:6px 14px;border-bottom:1px solid var(--paper2);text-align:right}\n.wr:last-child{border-bottom:0}\n.wr b{flex:1;font-size:17.5px;font-weight:500}\n.wr .st{font-size:13.5px;color:var(--ink2);display:flex;align-items:center;gap:5px}\n.wr .plus{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;background:var(--lb);color:var(--lc)}\n.wr .plus .ic{width:18px;height:18px}\n.wr.in b{font-weight:600}\n.meter{display:inline-flex;gap:2px}\n.meter i{width:5px;height:12px;border-radius:2px;background:var(--line)}\n.meter i.f{background:var(--lc)}\n\n/* מסך מילה / ציור */\n.topbar{display:flex;align-items:center;gap:10px;min-height:52px}\n.back{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:var(--sheet);border:1.5px solid var(--line)}\n.topbar h1{font-size:28px;font-weight:700;letter-spacing:-.015em;line-height:1.05}\n.topbar .sub{font-size:14px;color:var(--ink2)}\n.status{min-height:22px;font-size:15px;color:var(--ink2);display:flex;align-items:center;gap:8px}\n.status.good{color:var(--ok)}\n.status .pulse{display:inline-flex;gap:3px}\n.status .pulse i{width:6px;height:6px;border-radius:50%;background:var(--accent);animation:pl 1s infinite}\n.status .pulse i:nth-child(2){animation-delay:.15s}.status .pulse i:nth-child(3){animation-delay:.3s}\n@keyframes pl{0%,100%{opacity:.25;transform:scale(.8)}50%{opacity:1;transform:scale(1.1)}}\n.padSlot{flex:1;min-height:0;display:flex;align-items:center;justify-content:center}\n.sheetPad{position:relative;width:var(--ps,280px);height:var(--ps,280px)}\n.sheetPad::before,.sheetPad::after{content:\"\";position:absolute;top:-9px;width:62px;height:20px;background:rgba(242,196,92,.55);border-radius:3px;z-index:2;pointer-events:none}\n.sheetPad::before{right:18px;transform:rotate(4deg)}.sheetPad::after{left:18px;transform:rotate(-5deg)}\n#pad{width:100%;height:100%;display:block;background:#fff;border-radius:6px;touch-action:none;box-shadow:0 14px 28px -14px rgba(31,36,64,.45),0 2px 0 var(--line)}\n.padHint{position:absolute;inset:0;display:grid;place-items:center;color:#C9C3B5;font-size:18px;pointer-events:none;font-weight:500}\n.slots{display:grid;grid-template-columns:repeat(10,1fr);gap:5px}\n.slots button{aspect-ratio:1;border-radius:8px;background:var(--paper2);border:1.5px dashed var(--line);padding:0;overflow:hidden;position:relative}\n.slots button.f{background:#fff;border:1.5px solid var(--lc,var(--line))}\n.slots button.min{border-color:var(--ink3)}\n.slots canvas{width:100%;height:100%;display:block;image-rendering:auto}\n.tools{display:flex;gap:8px;align-items:center}\n.tools .btn.pri{flex:1}\n.acts{display:flex;gap:8px}\n.acts .btn{flex:1;font-size:15.5px;height:48px;padding:0 10px;white-space:nowrap}\n\n/* בדיקה */\n.guess{min-height:40px;font-size:26px;font-weight:700;text-align:center;display:flex;align-items:center;justify-content:center;gap:8px}\n.guess small{font-size:15px;color:var(--ink2);font-weight:500}\n.bars{display:flex;flex-direction:column;gap:5px;min-height:94px}\n#vTest .topbar{position:relative}\n.ddBtn{flex:none;display:flex;align-items:center;gap:6px;height:42px;padding:0 10px 0 12px;border-radius:13px;background:var(--sheet);border:1.5px solid var(--line);font-weight:600;font-size:14.5px}\n.ddBtn b{background:var(--ink);color:#fff;border-radius:999px;padding:0 8px;font-size:13px;line-height:20px}\n.ddBtn .chev{width:16px;height:16px;transform:rotate(90deg);transition:transform .2s}\n.ddBtn[aria-expanded=\"true\"] .chev{transform:rotate(-90deg)}\n.ddPanel{position:absolute;top:66px;left:16px;right:16px;z-index:6;max-height:52%;overflow-y:auto;background:var(--sheet);border:1.5px solid var(--line);border-radius:16px;box-shadow:var(--sh);padding:10px;display:flex;flex-wrap:wrap;gap:6px;align-content:flex-start}\n.ddPanel.hide{display:none}\n.ddPanel .mw{height:38px;font-size:15px;cursor:default}\n.bar{display:flex;align-items:center;gap:8px;height:28px;width:100%;text-align:right;font-size:15px}\n.bar .nm{width:92px;flex:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:500}\n.bar .tr{flex:1;height:14px;border-radius:7px;background:var(--paper2);overflow:hidden}\n.bar .fl{height:100%;border-radius:7px;background:var(--lc);transition:width .15s}\n.bar .pc{width:40px;text-align:left;color:var(--ink2)}\n.botTag{display:inline-flex;align-items:center;gap:3px;margin:0 6px;padding:0 7px;height:20px;border-radius:7px;background:var(--paper2);color:var(--ink2);font-style:normal;font-size:12px;font-weight:600;vertical-align:middle}\n.botTag .ic{width:13px;height:13px}\n.hint{font-size:13.5px;color:var(--ink2);text-align:center}\n.linkBtn{color:var(--accent);font-weight:600;font-size:14px;text-decoration:underline;text-underline-offset:3px;padding:4px 2px}\n.letterHd{position:sticky;top:0;z-index:1;padding:4px 14px;background:var(--paper2);color:var(--ink2);font-weight:700;font-size:14px}\n.wr:disabled{opacity:.45}\n.simTag{display:block;width:100%;font-style:normal;font-size:14px;font-weight:600;text-align:center}\n.guess{flex-wrap:wrap;row-gap:2px}\n.simTag.ok{color:var(--ok)}.simTag.no{color:var(--bad)}\n.cTag{display:inline-flex;margin-top:5px;height:24px;align-items:center;padding:0 9px;border-radius:8px;background:var(--ink);color:#fff;font-size:12.5px;font-weight:600}\n.curseBar{display:flex;align-items:center;gap:8px;min-height:40px;padding:0 14px;border-radius:13px;background:var(--ink);color:#fff;font-size:14.5px}\n.curseBar:empty{display:none}\n.curseBar b{font-size:16px}.curseBar span{opacity:.8;flex:1}.curseBar i{font-style:normal;font-weight:600;color:#F6D36B}\n.ghost{position:absolute;inset:0;width:100%;height:100%;z-index:2;pointer-events:none}\n.tinyWrap{position:absolute;inset:0;overflow:hidden;border-radius:6px;z-index:1;pointer-events:none}\n.tinyWrap i{position:absolute;left:33.2%;top:33.2%;width:33.6%;height:33.6%;border:2px dashed var(--accent);border-radius:4px;box-shadow:0 0 0 999px rgba(242,233,216,.85)}\n#pad{transition:none}\n.learnFx{position:absolute;inset:0;z-index:4;border-radius:6px;background:#1F2440;overflow:hidden;transition:opacity .25s;cursor:pointer}\n.learnFx.hide{display:none}\n.learnFx.out{opacity:0}\n.learnFx canvas{position:absolute;inset:0;width:100%;height:100%}\n.fxBrain{position:absolute;width:38%;height:38%;left:31%;top:23%;opacity:0;transform:scale(.55);transition:opacity .35s,transform .5s cubic-bezier(.16,1,.3,1)}\n.learnFx.b .fxBrain{opacity:1;transform:none}\n.learnFx.pulse .fxBrain{animation:bp .8s ease-in-out infinite}\n.learnFx.done .fxBrain{animation:none;transform:scale(1.12)}\n@keyframes bp{50%{transform:scale(1.07)}}\n.fxTxt{position:absolute;bottom:11%;left:0;right:0;text-align:center;color:#fff;font-weight:600;font-size:20px}\n.learnFx.done .fxTxt{color:#9BE3BC}\n.blind{position:absolute;inset:0;z-index:1;border-radius:6px;background:#fff;display:grid;place-items:center;pointer-events:none;color:#C9C3B5;font-weight:500;font-size:16px}\n\n/* כיכר */\n.chRow{width:100%;display:flex;align-items:center;gap:12px;padding:12px 14px;border-bottom:1px solid var(--paper2);text-align:right}\n.chRow:last-child{border-bottom:0}\n.chWord{font-size:20px;font-weight:700;line-height:1.1}\n.chMeta{font-size:13.5px;color:var(--ink2);margin-top:3px}\n.chPts{flex:none;text-align:center;min-width:58px;padding:6px 8px;border-radius:12px;background:var(--lb);color:var(--lc);font-weight:700;font-size:17px;line-height:1.1}\n.chPts small{display:block;font-size:11.5px;font-weight:500}\n.chPts.live{min-width:96px;padding:8px 12px;background:var(--ink);color:#fff}\n.chPts.live b{display:block;font-size:30px;line-height:1;color:#F6D36B}\n.chPts.live.low b{color:#fff}\n.chPts.live small{color:rgba(255,255,255,.75)}\n.chPts.tick b{animation:tick .25s cubic-bezier(.16,1,.3,1)}\n@keyframes tick{from{transform:scale(1.18)}to{transform:none}}\n.result .pts small{display:block;font-size:16px;font-weight:500;letter-spacing:0;margin-top:4px}\n.chSt{font-size:13.5px;font-weight:600}\n.chSt.open{color:var(--l2)}.chSt.solved{color:var(--ok)}\n.xBtn{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;color:var(--ink3);border:1.5px solid var(--line)}\n.empty{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center;padding:24px;color:var(--ink2)}\n.empty svg{width:84px;height:84px}\n.empty b{font-size:18px;color:var(--ink)}\n\n/* תוצאה */\n.result{position:absolute;inset:0;z-index:5;background:var(--paper);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:24px;text-align:center}\n.result .badge{width:92px;height:92px;border-radius:50%;display:grid;place-items:center;color:#fff}\n.result .badge .ic{width:48px;height:48px;stroke-width:3}\n.result.win .badge{background:var(--ok)}.result.lose .badge{background:var(--bad)}\n.result h2{font-size:30px;font-weight:700}\n.result p{font-size:17px;color:var(--ink2);max-width:30ch}\n.result .pts{font-size:64px;font-weight:700;line-height:1;letter-spacing:-.03em}\n.result.win .pts{color:var(--ok)}.result.lose .pts{color:var(--bad)}\n.result .formula{font-size:14px;color:var(--ink3)}\n.result .mini{width:120px;height:120px;border-radius:10px;background:#fff;box-shadow:var(--sh)}\n.result .pts,.result .badge{animation:pop .55s cubic-bezier(.16,1,.3,1) both}\n.result .pts{animation-delay:.12s}\n@keyframes pop{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:none}}\n\n/* דירוג */\n.meRank{display:flex;align-items:center;gap:14px;padding:14px 16px;border-radius:var(--r);background:var(--ink);color:#fff}\n.meRank b{font-size:34px;font-weight:700;line-height:1}\n.meRank span{font-size:14.5px;opacity:.85}\n.lr{display:flex;align-items:center;gap:12px;min-height:54px;padding:6px 14px;border-bottom:1px solid var(--paper2)}\n.lr:last-child{border-bottom:0}\n.lr .rk{width:30px;height:30px;border-radius:10px;display:grid;place-items:center;font-weight:700;background:var(--paper2);font-size:15px}\n.lr:nth-child(1) .rk{background:#F6D36B}.lr:nth-child(2) .rk{background:#DADDE8}.lr:nth-child(3) .rk{background:#EBC09C}\n.lr .nm{flex:1;font-size:17px;font-weight:500}\n.lr .nm small{display:block;font-size:13px;color:var(--ink2);font-weight:400}\n.lr .sc{font-weight:700;font-size:18px}\n.lr.me{background:var(--accentBg)}\n\n/* כניסה */\n#vLogin{justify-content:center;gap:16px;padding:24px 22px calc(24px + var(--safeB))}\n#vLogin .hero{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px}\n#vLogin .hero svg{width:116px;height:116px}\n#vLogin h1{font-size:40px;font-weight:700;letter-spacing:-.025em;line-height:1}\n#vLogin .lead{font-size:17px;color:var(--ink2);max-width:28ch}\n.field{display:flex;flex-direction:column;gap:6px}\n.field span{font-size:14.5px;font-weight:600;color:var(--ink2)}\n.field input{height:54px;border-radius:15px;border:1.5px solid var(--line);background:var(--sheet);padding:0 16px;font-size:18px;outline:none}\n.field input:focus{border-color:var(--ink)}\n.field input.code{letter-spacing:.3em;text-align:center;font-size:24px;font-weight:600}\n.err{color:var(--bad);font-size:15px;min-height:20px;text-align:center}\n.codeBox{display:flex;flex-direction:column;align-items:center;gap:6px;padding:18px;border-radius:var(--r);background:var(--sheet);border:2px dashed var(--accent)}\n.codeBox b{font-size:52px;letter-spacing:.18em;font-weight:700;line-height:1}\n.codeBox span{font-size:15px;color:var(--ink2);text-align:center}\n.steps{list-style:none;padding:0;display:flex;flex-direction:column;gap:4px;font-size:14.5px;color:var(--ink2)}\n\n/* גיליונות */\n.scrim{position:fixed;inset:0;background:rgba(31,36,64,.38);z-index:20;display:none}\n.scrim.on{display:block}\n.sheet{position:fixed;left:0;right:0;bottom:0;z-index:21;background:var(--paper);border-radius:24px 24px 0 0;padding:10px 18px calc(18px + var(--safeB));max-height:78%;display:flex;flex-direction:column;gap:12px;transform:translateY(105%);transition:transform .3s cubic-bezier(.16,1,.3,1)}\n.sheet.on{transform:none}\n.sheet .grab{width:44px;height:5px;border-radius:3px;background:var(--line);align-self:center}\n.sheet h3{font-size:21px;font-weight:700}\n.nl{display:flex;flex-direction:column;overflow-y:auto;border-radius:var(--r);background:var(--sheet);border:1.5px solid var(--line)}\n.nr{display:flex;gap:10px;padding:12px 14px;border-bottom:1px solid var(--paper2);font-size:15px}\n.nr:last-child{border-bottom:0}\n.nr b{flex:none;font-weight:700}\n.nr.win b{color:var(--ok)}.nr.lose b{color:var(--bad)}\n.nr.new{background:#FFF8E6}\n.recBtn{margin-top:6px;height:34px;padding:0 12px;border-radius:10px;background:var(--paper2);color:var(--ink);font-weight:600;font-size:14px;display:inline-flex;align-items:center;gap:6px}\n.recBtn .ic{width:16px;height:16px}\n.tries{display:flex;gap:8px;overflow-x:auto;padding:2px 16px 6px;flex:none;scrollbar-width:none;align-items:center}\n.tries>small{flex:none;color:var(--ink2);font-size:13px;font-weight:600}\n.tryC{flex:none;display:flex;flex-direction:column;align-items:center;gap:2px;background:none}\n.tryC canvas{width:52px;height:52px;border-radius:10px;background:#fff;border:2px solid var(--bad);image-rendering:auto}\n.tryC span{font-size:12.5px;font-weight:700;color:var(--bad)}\n#recC{display:block;width:min(280px,72vw);height:auto;aspect-ratio:1;margin:6px auto 10px;background:#fff;border-radius:16px;box-shadow:var(--sh)}\n.recRes{min-height:58px;text-align:center;font-size:16px;opacity:0;transform:translateY(6px);transition:opacity .35s,transform .35s}\n.recRes.on{opacity:1;transform:none}\n.recRes b{display:block;font-size:22px}\n.recRes.win b{color:var(--ok)}.recRes.lose b{color:var(--bad)}\n.recRow{width:100%;display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--paper2);text-align:right;background:none;font-size:16px}\n.recRow b{flex:1;font-weight:600}.recRow .num{font-weight:700}.recRow.win .num{color:var(--ok)}.recRow.lose .num{color:var(--bad)}\n.nr time{display:block;font-size:12.5px;color:var(--ink3);margin-top:2px}\n\n#toast{position:fixed;top:calc(10px + var(--safeT));left:16px;right:16px;z-index:30;padding:13px 16px;border-radius:16px;background:var(--ink);color:#fff;font-weight:500;font-size:15.5px;box-shadow:var(--sh);transform:translateY(-16px);opacity:0;visibility:hidden;pointer-events:none;transition:transform .35s cubic-bezier(.16,1,.3,1),opacity .25s,visibility 0s .35s;text-align:center}\n#toast.on{transform:none;opacity:1;visibility:visible;transition:transform .35s cubic-bezier(.16,1,.3,1),opacity .2s}\nbdi{unicode-bidi:isolate;direction:ltr}\n\n#desk{position:fixed;inset:0;z-index:40;display:none;place-items:center;background:var(--paper);text-align:center;padding:40px}\n#desk.on{display:grid}\n#desk div{max-width:440px;display:flex;flex-direction:column;align-items:center;gap:12px}\n#desk svg{width:120px;height:120px}\n#desk h1{font-size:44px}\n#desk p{font-size:18px;color:var(--ink2)}\n\n@media (min-width:760px){\n body{background:#2A2F4F;background-image:none}\n #app{left:50%;right:auto;width:430px;margin-left:-215px;top:16px;bottom:16px;border-radius:28px;overflow:hidden;background:var(--paper);background-image:linear-gradient(rgba(31,36,64,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(31,36,64,.045) 1px,transparent 1px);background-size:22px 22px;box-shadow:0 30px 60px -20px rgba(0,0,0,.6)}\n .sheet,#toast{left:50%;right:auto;width:430px;margin-left:-215px}\n #toast{width:398px;margin-left:-199px}\n .sheet{bottom:16px;border-radius:24px;transform:translateY(calc(100% + 40px))}\n .sheet.on{transform:none}\n}\n@media (max-height:640px){header{height:50px}.topbar h1{font-size:24px}.btn{height:48px}.tool{width:44px;height:44px}nav button{height:48px}.brainBar{padding:8px 12px}.brainBar svg.mascot{width:44px;height:44px}}\n</style>\n</head>\n<body>\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n <symbol id=\"i-brain\" viewBox=\"0 0 24 24\"><path d=\"M12 5.5C10.6 3.8 7.6 4 7 6.2 5 6.3 3.9 8.3 4.8 10c-1.4 1.1-1.1 3.5.5 4.3-.1 1.9 1.9 3.3 3.6 2.6.9 1.3 2.5 1.4 3.1.4.6 1 2.2.9 3.1-.4 1.7.7 3.7-.7 3.6-2.6 1.6-.8 1.9-3.2.5-4.3.9-1.7-.2-3.7-2.2-3.8-.6-2.2-3.6-2.4-5-.7z\"/><path d=\"M12 5.5v13\"/></symbol>\n <symbol id=\"i-plaza\" viewBox=\"0 0 24 24\"><circle cx=\"8\" cy=\"8\" r=\"3\"/><circle cx=\"16.5\" cy=\"9\" r=\"2.5\"/><path d=\"M2.5 19c.6-3.3 2.8-5 5.5-5s4.9 1.7 5.5 5M14 14.3c.8-.4 1.6-.6 2.5-.6 2.4 0 4.3 1.5 4.9 4.3\"/></symbol>\n <symbol id=\"i-trophy\" viewBox=\"0 0 24 24\"><path d=\"M8 4h8v5a4 4 0 0 1-8 0z\"/><path d=\"M8 6H4.5a3 3 0 0 0 3.6 4M16 6h3.5a3 3 0 0 1-3.6 4M12 13v4M8.5 20h7M10 17h4\"/></symbol>\n <symbol id=\"i-bell\" viewBox=\"0 0 24 24\"><path d=\"M6 16V11a6 6 0 0 1 12 0v5l1.5 2h-15z\"/><path d=\"M10 20.5a2.2 2.2 0 0 0 4 0\"/></symbol>\n <symbol id=\"i-star\" viewBox=\"0 0 24 24\"><path d=\"m12 3.5 2.6 5.3 5.8.8-4.2 4.1 1 5.8-5.2-2.7-5.2 2.7 1-5.8-4.2-4.1 5.8-.8z\" fill=\"currentColor\"/></symbol>\n <symbol id=\"i-pen\" viewBox=\"0 0 24 24\"><path d=\"M4 20l1-4.5L15.5 5a2.1 2.1 0 0 1 3 3L8 18.5z\"/><path d=\"M13.5 7l3 3\"/></symbol>\n <symbol id=\"i-eraser\" viewBox=\"0 0 24 24\"><path d=\"M9 19.5h11M4.6 14.6l8.8-8.8a2 2 0 0 1 2.8 0l2.4 2.4a2 2 0 0 1 0 2.8L11 19.5H8.5l-3.9-3.9a.7.7 0 0 1 0-1z\"/><path d=\"M9 10.5l5 5\"/></symbol>\n <symbol id=\"i-trash\" viewBox=\"0 0 24 24\"><path d=\"M4.5 7h15M10 4h4M6.5 7l1 12.5h9l1-12.5M10 11v5M14 11v5\"/></symbol>\n <symbol id=\"i-dice\" viewBox=\"0 0 24 24\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"3.5\"/><circle cx=\"9\" cy=\"9\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"15\" cy=\"15\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"15\" cy=\"9\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"9\" cy=\"15\" r=\"1.2\" fill=\"currentColor\"/></symbol>\n <symbol id=\"i-search\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"6.5\"/><path d=\"m20 20-4.2-4.2\"/></symbol>\n <symbol id=\"i-back\" viewBox=\"0 0 24 24\"><path d=\"M9 5l7 7-7 7\"/></symbol>\n <symbol id=\"i-check\" viewBox=\"0 0 24 24\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></symbol>\n <symbol id=\"i-x\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6 6 18\"/></symbol>\n <symbol id=\"i-plus\" viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></symbol>\n <symbol id=\"i-send\" viewBox=\"0 0 24 24\"><path d=\"M20 4 3.5 11l7 2.5L13 20.5z\"/><path d=\"m10.5 13.5 4-4\"/></symbol>\n <symbol id=\"i-flag\" viewBox=\"0 0 24 24\"><path d=\"M6 21V4M6 4h11l-2.5 4L17 12H6\"/></symbol>\n <symbol id=\"i-bot\" viewBox=\"0 0 24 24\"><rect x=\"5\" y=\"8\" width=\"14\" height=\"11\" rx=\"3\"/><path d=\"M12 8V5M9.5 13h.01M14.5 13h.01M9.5 16.5h5M3 13v2M21 13v2\"/><circle cx=\"12\" cy=\"4\" r=\"1\"/></symbol>\n <symbol id=\"i-flask\" viewBox=\"0 0 24 24\"><path d=\"M9.5 3.5h5M10.5 3.5v5.5L5 18.5a1.5 1.5 0 0 0 1.3 2h11.4a1.5 1.5 0 0 0 1.3-2L13.5 9V3.5\"/><path d=\"M7.5 14.5h9\"/></symbol>\n <symbol id=\"i-clear\" viewBox=\"0 0 24 24\"><path d=\"M4 7h16M7 7v12.5h10V7M9 4h6\"/><path d=\"m10 11 4 5M14 11l-4 5\"/></symbol>\n</svg>\n\n<div id=\"app\">\n <header>\n  <div class=\"logo\"><svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><use href=\"#mascotSmall\"/></svg><b>צייר המוחות</b></div>\n  <button class=\"pill num\" id=\"hScore\" aria-label=\"הניקוד שלי\"><svg class=\"ic\"><use href=\"#i-star\"/></svg><span>0</span></button>\n  <button class=\"iconBtn\" id=\"hBell\" aria-label=\"התראות\"><svg class=\"ic\"><use href=\"#i-bell\"/></svg><span class=\"dot hide\" id=\"bellDot\"></span></button>\n  <button class=\"iconBtn ava\" id=\"hMe\" aria-label=\"הפרופיל שלי\">?</button>\n </header>\n <main>\n  <!-- כניסה -->\n  <section class=\"view\" id=\"vLogin\">\n   <div class=\"hero\">\n    <svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><use href=\"#mascotBig\"/></svg>\n    <h1>צייר המוחות</h1>\n    <p class=\"lead\">מלמדים מוח מלאכותי לזהות ציורים – ואז מאתגרים את המוחות של כולם.</p>\n   </div>\n   <div class=\"seg\" id=\"loginSeg\"><button class=\"on\" data-m=\"new\">שחקן חדש</button><button data-m=\"old\">יש לי קוד</button></div>\n   <div id=\"lNew\" class=\"field\"><span>איך קוראים לך?</span><input id=\"inName\" maxlength=\"14\" autocomplete=\"nickname\" placeholder=\"השם שלך במשחק\"></div>\n   <div id=\"lOld\" class=\"hide\" style=\"display:flex;flex-direction:column;gap:12px\">\n    <label class=\"field\"><span>שם</span><input id=\"inName2\" maxlength=\"14\" placeholder=\"השם במשחק\"></label>\n    <label class=\"field\"><span>קוד אישי</span><input id=\"inCode\" class=\"code num\" maxlength=\"4\" inputmode=\"numeric\" placeholder=\"••••\"></label>\n   </div>\n   <div id=\"lCode\" class=\"codeBox hide\"><span>הקוד האישי שלך</span><b class=\"num\" id=\"codeShow\">0000</b><span>צלמו או רשמו אותו –<br>בעזרתו נכנסים מכל טלפון.</span></div>\n   <div class=\"err\" id=\"lErr\"></div>\n   <button class=\"btn pri\" id=\"lGo\">יוצרים שחקן</button>\n  </section>\n\n  <!-- המוח שלי -->\n  <section class=\"view\" id=\"vRoom\">\n   <div class=\"brainBar\">\n    <svg class=\"mascot\" viewBox=\"0 0 64 64\" id=\"roomMascot\" aria-hidden=\"true\"></svg>\n    <div class=\"grow\"><h2 id=\"rTitle\">המוח שלך ריק</h2><p id=\"rSub\">בחרו מילה מהמאגר והתחילו לצייר</p></div>\n    <button class=\"btn sm\" id=\"rTest\"><svg class=\"ic\"><use href=\"#i-flask\"/></svg>בדיקה</button>\n   </div>\n   <button class=\"myWordsBtn\" id=\"myWords\"></button>\n   <div class=\"seg\" id=\"lvSeg\">\n    <button class=\"lv1 on\" data-l=\"1\"><i></i>פשוטות</button><button class=\"lv2\" data-l=\"2\"><i></i>בינוניות</button><button class=\"lv3\" data-l=\"3\"><i></i>מורכבות</button>\n   </div>\n   <div class=\"search\">\n    <label><svg class=\"ic\"><use href=\"#i-search\"/></svg><input id=\"q\" placeholder=\"חיפוש מילה במאגר\" enterkeyhint=\"search\"></label>\n    <button class=\"tool\" id=\"rnd\" aria-label=\"מילה אקראית\"><svg class=\"ic\"><use href=\"#i-dice\"/></svg></button>\n    <button class=\"tool\" id=\"addW\" aria-label=\"הוספת מילה משלי\" style=\"color:var(--l4);border-color:var(--l4)\"><svg class=\"ic\"><use href=\"#i-plus\"/></svg></button>\n   </div>\n   <div class=\"list\" id=\"wordList\"></div>\n  </section>\n\n  <!-- אימון מילה -->\n  <section class=\"view\" id=\"vWord\">\n   <div class=\"topbar\">\n    <button class=\"back\" data-back aria-label=\"חזרה\"><svg class=\"ic\"><use href=\"#i-back\"/></svg></button>\n    <div class=\"grow\"><h1 id=\"wTitle\">מילה</h1><div class=\"sub\" id=\"wSub\"></div></div>\n    <button class=\"xBtn\" id=\"wDel\" aria-label=\"מחיקת המילה מהמוח\"><svg class=\"ic\"><use href=\"#i-trash\"/></svg></button>\n   </div>\n   <div class=\"status\" id=\"wStatus\"></div>\n   <div class=\"padSlot\" data-pad></div>\n   <div class=\"slots\" id=\"slots\"></div>\n   <div class=\"tools\">\n    <button class=\"tool sel\" data-tool=\"pen\" aria-label=\"עט\"><svg class=\"ic\"><use href=\"#i-pen\"/></svg></button>\n    <button class=\"tool\" data-tool=\"eraser\" aria-label=\"מחק\"><svg class=\"ic\"><use href=\"#i-eraser\"/></svg></button>\n    <button class=\"tool\" data-clear aria-label=\"ניקוי הלוח\"><svg class=\"ic\"><use href=\"#i-clear\"/></svg></button>\n    <button class=\"btn pri\" id=\"wSave\"><svg class=\"ic\"><use href=\"#i-check\"/></svg>שמור בזיכרון</button>\n   </div>\n   <div class=\"acts\">\n    <button class=\"btn\" id=\"wTest\" disabled><svg class=\"ic\"><use href=\"#i-flask\"/></svg>בדיקת מוח</button>\n    <button class=\"btn\" id=\"wPub\" disabled><svg class=\"ic\"><use href=\"#i-flag\"/></svg>פרסם אתגר</button>\n   </div>\n  </section>\n\n  <!-- בדיקה -->\n  <section class=\"view\" id=\"vTest\">\n   <div class=\"topbar\">\n    <button class=\"back\" data-back aria-label=\"חזרה\"><svg class=\"ic\"><use href=\"#i-back\"/></svg></button>\n    <div class=\"grow\"><h1>בדיקת המוח</h1><div class=\"sub\">ציירו – והמוח ינחש</div></div>\n    <button class=\"ddBtn\" id=\"tWordsBtn\" aria-expanded=\"false\"><span>המילים במוח</span><b class=\"num\" id=\"tWordsN\">0</b><svg class=\"ic chev\"><use href=\"#i-back\"/></svg></button>\n   </div>\n   <div class=\"ddPanel hide\" id=\"tWords\"></div>\n   <div class=\"padSlot\" data-pad></div>\n   <div class=\"guess\" id=\"tGuess\"></div>\n   <div class=\"bars\" id=\"tBars\"></div>\n   <div class=\"hint\">טעה? לחצו על המילה הנכונה – המוח ילמד מזה · <button class=\"linkBtn\" id=\"tOther\">מילה אחרת</button></div>\n   <div class=\"tools\">\n    <button class=\"tool sel\" data-tool=\"pen\" aria-label=\"עט\"><svg class=\"ic\"><use href=\"#i-pen\"/></svg></button>\n    <button class=\"tool\" data-tool=\"eraser\" aria-label=\"מחק\"><svg class=\"ic\"><use href=\"#i-eraser\"/></svg></button>\n    <button class=\"btn grow\" data-clear><svg class=\"ic\"><use href=\"#i-clear\"/></svg>ציור חדש</button>\n   </div>\n  </section>\n\n  <!-- כיכר -->\n  <section class=\"view\" id=\"vSquare\">\n   <div class=\"seg\" id=\"sqSeg\"><button class=\"on\" data-s=\"open\">אתגרים פתוחים</button><button data-s=\"mine\">האתגרים שלי</button></div>\n   <div class=\"list\" id=\"sqList\"></div>\n  </section>\n\n  <!-- ציור אתגר -->\n  <section class=\"view\" id=\"vDraw\">\n   <div class=\"topbar\">\n    <button class=\"back\" data-back aria-label=\"חזרה\"><svg class=\"ic\"><use href=\"#i-back\"/></svg></button>\n    <div class=\"grow\"><div class=\"sub\">ציירו:</div><h1 id=\"dWord\">מילה</h1></div>\n    <div class=\"chPts\" id=\"dPts\"></div>\n   </div>\n   <div class=\"status\" id=\"dSub\"></div>\n   <div class=\"tries hide\" id=\"dTries\"></div>\n   <div class=\"padSlot\" data-pad></div>\n   <div class=\"tools\">\n    <button class=\"tool sel\" data-tool=\"pen\" aria-label=\"עט\"><svg class=\"ic\"><use href=\"#i-pen\"/></svg></button>\n    <button class=\"tool\" data-tool=\"eraser\" aria-label=\"מחק\"><svg class=\"ic\"><use href=\"#i-eraser\"/></svg></button>\n    <button class=\"tool\" data-clear aria-label=\"ניקוי הלוח\"><svg class=\"ic\"><use href=\"#i-clear\"/></svg></button>\n    <button class=\"btn pri\" id=\"dSend\"><svg class=\"ic\"><use href=\"#i-send\"/></svg>שלח למוח</button>\n   </div>\n   <div class=\"curseBar\" id=\"dCurse\"></div>\n   <div class=\"result hide\" id=\"dRes\"></div>\n  </section>\n\n  <!-- דירוג -->\n  <section class=\"view\" id=\"vLeaders\">\n   <div class=\"meRank\"><b class=\"num\" id=\"lbRank\">–</b><div><div style=\"font-size:18px;font-weight:600\" id=\"lbName\"></div><span id=\"lbScore\"></span></div></div>\n   <div class=\"list\" id=\"lbList\"></div>\n  </section>\n </main>\n <nav id=\"nav\">\n  <button data-v=\"vRoom\" class=\"on\"><svg class=\"ic\"><use href=\"#i-brain\"/></svg>המוח שלי</button>\n  <button data-v=\"vSquare\"><svg class=\"ic\"><use href=\"#i-plaza\"/></svg>הכיכר</button>\n  <button data-v=\"vLeaders\"><svg class=\"ic\"><use href=\"#i-trophy\"/></svg>דירוג</button>\n </nav>\n</div>\n\n<div class=\"scrim\" id=\"scrim\"></div>\n<div class=\"sheet\" id=\"shNotes\"><div class=\"grab\"></div><h3>התראות</h3><div class=\"nl\" id=\"noteList\"></div></div>\n<div class=\"sheet\" id=\"shMe\"><div class=\"grab\"></div><h3 id=\"meName\"></h3>\n <div class=\"codeBox\"><span>הקוד האישי שלך</span><b class=\"num\" id=\"meCode\"></b><span>בעזרתו נכנסים מכל טלפון</span></div>\n <button class=\"btn hide\" id=\"purgeBtn\" style=\"color:var(--bad);margin-bottom:8px\">ניקוי שחקנים שאינם רובוטים</button>\n <button class=\"btn dark\" id=\"pushBtn\"><svg class=\"ic\"><use href=\"#i-bell\"/></svg>הפעלת התראות</button>\n <ul class=\"steps hide\" id=\"iosSteps\"><li>באייפון – התראות עובדות רק מהמסך הראשי:</li><li>1. לחצו על כפתור השיתוף בספארי</li><li>2. בחרו \"הוספה למסך הבית\"</li><li>3. פתחו את צייר המוחות מהאייקון החדש</li></ul>\n <button class=\"btn\" id=\"logout\">התנתקות</button>\n</div>\n<div class=\"sheet\" id=\"shAsk\"><div class=\"grab\"></div><h3 id=\"askT\"></h3><p id=\"askP\" style=\"color:var(--ink2);font-size:16px\"></p><div class=\"row\"><button class=\"btn grow\" id=\"askNo\">ביטול</button><button class=\"btn pri grow\" id=\"askYes\">אישור</button></div></div>\n<div class=\"sheet tall\" id=\"shPick\"><div class=\"grab\"></div><h3>מה ציירת?</h3><div class=\"search\"><label><svg class=\"ic\"><use href=\"#i-search\"/></svg><input id=\"pickQ\" placeholder=\"חיפוש בכל 300 המילים\" enterkeyhint=\"search\"></label></div><div class=\"list\" id=\"pickGrid\"></div></div>\n<div class=\"sheet\" id=\"shRec\"><div class=\"grab\"></div><h3 id=\"recT\"></h3><canvas id=\"recC\" width=\"280\" height=\"280\"></canvas><div class=\"recRes\" id=\"recRes\"></div><div class=\"row\"><button class=\"btn grow\" id=\"recAgain\">שוב</button><button class=\"btn pri grow\" id=\"recClose\">סגירה</button></div></div>\n<div class=\"sheet tall\" id=\"shRecs\"><div class=\"grab\"></div><h3 id=\"recsT\">מי צייר</h3><div class=\"list\" id=\"recsList\"></div></div>\n<div class=\"sheet\" id=\"shEx\"><div class=\"grab\"></div><h3 id=\"exT\"></h3><canvas id=\"exC\" width=\"280\" height=\"280\" style=\"display:block;width:min(280px,72vw);height:auto;aspect-ratio:1;margin:6px auto 8px;background:#fff;border-radius:16px;box-shadow:var(--sh)\"></canvas><p id=\"exP\" style=\"text-align:center;color:var(--ink2);font-size:15px;min-height:22px;margin-bottom:10px\"></p><div class=\"row\"><button class=\"btn\" id=\"exPrev\" aria-label=\"הקודם\"><svg class=\"ic\"><use href=\"#i-back\"/></svg></button><button class=\"btn grow\" id=\"exDel\" style=\"color:var(--bad)\">מחיקה</button><button class=\"btn pri grow\" id=\"exClose\">סגירה</button><button class=\"btn\" id=\"exNext\" aria-label=\"הבא\"><svg class=\"ic\" style=\"transform:scaleX(-1)\"><use href=\"#i-back\"/></svg></button></div></div>\n<div class=\"sheet\" id=\"shAdd\"><div class=\"grab\"></div><h3>מילה משלי</h3><p style=\"color:var(--ink2);font-size:15px;margin-bottom:10px\">מילה אחת בעברית שלא נמצאת במאגר. ניקוד כמו מילה פשוטה.</p><div class=\"search\"><label><svg class=\"ic\"><use href=\"#i-pen\"/></svg><input id=\"addQ\" placeholder=\"למשל: אגרטל\" maxlength=\"14\" enterkeyhint=\"done\" autocomplete=\"off\"></label></div><div class=\"addErr\" id=\"addErr\"></div><div class=\"row\"><button class=\"btn grow\" id=\"addNo\">ביטול</button><button class=\"btn pri grow\" id=\"addYes\">הוספה</button></div></div>\n<div class=\"sheet tall\" id=\"shMine\"><div class=\"grab\"></div><h3 id=\"mineTitle\">המילים שלי</h3><div class=\"search\"><label><svg class=\"ic\"><use href=\"#i-search\"/></svg><input id=\"mineQ\" placeholder=\"חיפוש במילים שלי\"></label></div><div class=\"list\" id=\"mineList\"></div></div>\n<div id=\"toast\"></div>\n<div id=\"desk\"><div><svg viewBox=\"0 0 64 64\"><use href=\"#mascotBig\"/></svg><h1>צייר המוחות</h1><p>המשחק בנוי לטלפון.<br>פתחו את הכתובת הזאת בנייד:</p><p class=\"num\" style=\"font-weight:600;color:var(--ink);direction:ltr\">__ORIGIN__</p></div></div>\n\n<!-- קמע: מוח מצויר -->\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n <defs>\n  <g id=\"mascotBody\">\n   <path d=\"M32 12c-5-4.6-13.6-3.4-15.8 2.8-6 .3-9.3 6.5-6.8 11.6-4 3.4-3.4 10.7 1.4 13.2-.3 5.7 5.6 9.9 11 7.9 2.6 4 7.6 4.3 10.2 1.4 2.6 2.9 7.6 2.6 10.2-1.4 5.4 2 11.3-2.2 11-7.9 4.8-2.5 5.4-9.8 1.4-13.2 2.5-5.1-.8-11.3-6.8-11.6C45.6 8.6 37 7.4 32 12z\" fill=\"#FFE3D6\" stroke=\"#1F2440\" stroke-width=\"2.6\" stroke-linejoin=\"round\"/>\n   <path d=\"M32 13v34M24 21c3 1.2 4.4 3.8 3.8 7M40 21c-3 1.2-4.4 3.8-3.8 7M19.5 34c3.2-1.5 6.6-.9 8.6 1.7M44.5 34c-3.2-1.5-6.6-.9-8.6 1.7\" fill=\"none\" stroke=\"#1F2440\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n  </g>\n  <g id=\"mascotSmall\"><use href=\"#mascotBody\"/><circle cx=\"24\" cy=\"29\" r=\"2.6\" fill=\"#E2461F\"/><circle cx=\"40\" cy=\"29\" r=\"2.6\" fill=\"#E2461F\"/><circle cx=\"32\" cy=\"41\" r=\"2.6\" fill=\"#E2461F\"/></g>\n  <g id=\"mascotBig\"><use href=\"#mascotBody\"/><circle cx=\"24\" cy=\"29\" r=\"2.6\" fill=\"#E2461F\"/><circle cx=\"40\" cy=\"29\" r=\"2.6\" fill=\"#E2461F\"/><circle cx=\"32\" cy=\"41\" r=\"2.6\" fill=\"#E2461F\"/><circle cx=\"18\" cy=\"24\" r=\"2\" fill=\"#6343D6\"/><circle cx=\"46\" cy=\"24\" r=\"2\" fill=\"#1A8E58\"/><circle cx=\"21\" cy=\"40\" r=\"2\" fill=\"#B87400\"/><circle cx=\"43\" cy=\"40\" r=\"2\" fill=\"#6343D6\"/></g>\n </defs>\n</svg>\n\n<script>\n'use strict';\nconst WORDS=/*__WORDS__*/null;\nconst WFILTER=/*__FILTER__*/null;\nfunction wordProblem(w, F = WFILTER) {\n  w = String(w || '').trim();\n  if (!w) return 'כתבו מילה';\n  if (/\\s/.test(w)) return 'רק מילה אחת, בלי רווחים';\n  if (!/^[\\u05D0-\\u05EA'\"׳״-]+$/.test(w)) return 'רק אותיות בעברית';\n  const L = w.replace(/['\"׳״-]/g, '').length;\n  if (L < 2) return 'מילה קצרה מדי';\n  if (L > 12) return 'מילה ארוכה מדי';\n  const norm = s => s.replace(/['\"׳״-]/g, '').replace(/[ךםןףץ]/g, c => 'כמנפצ'['ךםןףץ'.indexOf(c)]).replace(/(.)\\1+/g, '$1');\n  const bad = new Set(F.bad.map(norm)), sub = F.sub.map(norm), n = norm(w), forms = [n];\n  for (let i = 1; i <= 3 && i < n.length - 1; i++) { if (!'הובכלש'.includes(n[i - 1])) break; forms.push(n.slice(i)); }\n  if (forms.some(f => bad.has(f)) || sub.some(s => n.includes(s))) return 'המילה הזאת לא מתאימה למשחק';\n  return '';\n}\nconst MODE=/*__MODE__*/'ink';\nconst SEND_LABEL=MODE==='ink'?'אתגר את המוח':'שלח למוח';\nconst INK_MAX=10;\nconst inkMult=r=>Math.round((1+(INK_MAX-1)*Math.min(1,Math.max(0,(1-r)/0.85)))*10)/10;\nfunction liveL(){if(!hasInk)return 0;return inkLen/Math.max(bx1-bx0+18,by1-by0+18,1);}\nfunction livePts(){const c=cur.ch;if(!c)return 0;return hasInk?Math.round(c.min*inkMult(liveL()/(c.Lmed||3))):c.max;}\nlet liveShown=-1;\nfunction paintLive(){const el=$('#dPts');if(!el||MODE!=='ink'||!cur.ch||cur.view!=='vDraw')return;const v=livePts();if(v===liveShown)return;liveShown=v;\n el.innerHTML=`<b class=\"num\">${v}</b><small>נקודות</small>`;el.classList.toggle('low',v<=cur.ch.min);el.classList.remove('tick');void el.offsetWidth;el.classList.add('tick');}\nconst $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];\nconst QS=new URLSearchParams(location.search);\nconst HM=location.hash.match(/^#sim-(\\d+)$/);\nconst NS=HM||QS.get('ns')==='test'?'test':'live',SLOT=HM?HM[1]:(QS.get('slot')||'0'),SIM=!!HM||QS.get('sim')==='1',DEMO=!!window.__DEMO,SOLO=!!window.__SOLO;\nconst KEY=`tz_${NS}_${SLOT}_`;\nconst N=28,IN=N*N,H=64,LR=0.015,MIN_EX=1,MAX_EX=10,MIN_WORDS=5;\nconst BASE={1:10,2:20,3:30,4:10},LVNAME={1:'פשוטה',2:'בינונית',3:'מורכבת',4:'חופשית'};\nfor(const k of [1,2,3])WORDS[k]=WORDS[k].slice().sort((a,b)=>a.localeCompare(b,'he'));\nconst LVL0=new Map();for(const k of [1,2,3])for(const w of WORDS[k])LVL0.set(w,k);\n// מילה שלא מהמאגר = מילה חופשית (רמה 4, ניקוד כמו פשוטה)\nconst LVL={get:w=>LVL0.get(w)||4,has:w=>LVL0.has(w)};\n\n/* ---------- אחסון ---------- */\nconst ls={get(k,d){try{const v=localStorage.getItem(KEY+k);return v==null?d:JSON.parse(v);}catch(e){return d;}},set(k,v){try{localStorage.setItem(KEY+k,JSON.stringify(v));}catch(e){}},del(k){try{localStorage.removeItem(KEY+k);}catch(e){}}};\nlet AUTH=ls.get('auth',null);\n\n/* ---------- שרת ---------- */\nasync function api(path,opt={}){\n const r=await fetch(`/api/${path}${path.includes('?')?'&':'?'}ns=${NS}`,{method:opt.method||'GET',headers:{'content-type':'application/json',...(AUTH?{authorization:'Bearer '+AUTH.token}:{})},body:opt.body?JSON.stringify(opt.body):undefined});\n let j={};try{j=await r.json();}catch(e){}\n if(r.status===401&&AUTH&&path!=='login'){logout(true);}\n if(!r.ok)throw new Error(j.error||'שגיאת רשת');\n return j;\n}\n\n/* ---------- ניקוד ---------- */\nconst sizeBonus=k=>Math.min(2,Math.max(0,(k-MIN_WORDS)*0.05));\nconst riskMult=n=>Math.round((3-(Math.min(MAX_EX,Math.max(1,n))-1)*2/9)*10)/10;\nconst SIM_OK=0.8,SIM_LO=0.66,SIM_HI=0.95,SIM_TF=[-45,-30,-15,0,15,30,45];\n// אותו עובי קו לכולם: הופכים לשחור־לבן ומעבים ב־1 פיקסל, כך שמשווים רק צורה\nfunction thickN(d){const b=new Float32Array(IN);for(let y=0;y<N;y++)for(let x=0;x<N;x++){let on=0;for(let a=-1;a<=1&&!on;a++)for(let c=-1;c<=1;c++){const yy=y+a,xx=x+c;if(yy>=0&&yy<N&&xx>=0&&xx<N&&d[yy*N+xx]>=6){on=1;break;}}b[y*N+x]=on?15:0;}return b;}\nfunction prep(d){return blur2(thickN(d));}\nfunction blur2(d){let o=Float32Array.from(d);for(let pass=0;pass<2;pass++){const n=new Float32Array(IN);for(let y=0;y<N;y++)for(let x=0;x<N;x++){let s=0,c=0;for(let a=-1;a<=1;a++)for(let b=-1;b<=1;b++){const yy=y+a,xx=x+b;if(yy<0||yy>=N||xx<0||xx>=N)continue;s+=o[yy*N+xx];c++;}n[y*N+x]=s/c;}o=n;}return o;}\nfunction cosSim(a,b){let ma=0,mb=0;const n=a.length;for(let i=0;i<n;i++){ma+=a[i];mb+=b[i];}ma/=n;mb/=n;let s=0,x=0,y=0;for(let i=0;i<n;i++){const u=a[i]-ma,v=b[i]-mb;s+=u*v;x+=u*u;y+=v*v;}return s/Math.sqrt(x*y+1e-9);}\n\n// הטיה קלה בלבד: סיבוב בזווית (מעלות), בלי היפוכים\nfunction tf8(d,deg){if(!deg)return d;const o=new d.constructor(d.length),r=deg*Math.PI/180,c=Math.cos(r),s=Math.sin(r),m=(N-1)/2,isI=!(d instanceof Float32Array);for(let y=0;y<N;y++)for(let x=0;x<N;x++){const u=c*(x-m)+s*(y-m)+m,v=-s*(x-m)+c*(y-m)+m,x0=Math.floor(u),y0=Math.floor(v),fx=u-x0,fy=v-y0;let val=0;for(const [dx,dy,w] of [[0,0,(1-fx)*(1-fy)],[1,0,fx*(1-fy)],[0,1,(1-fx)*fy],[1,1,fx*fy]]){const xx=x0+dx,yy=y0+dy;if(xx>=0&&xx<N&&yy>=0&&yy<N)val+=d[yy*N+xx]*w;}o[y*N+x]=isI?Math.round(val):val;}return o;}\nfunction simMax(bd,exB){let m=0;for(const k of SIM_TF){const t=tf8(bd,k);for(const e of exB)m=Math.max(m,cosSim(t,e));}return m;}\nconst simFactor=s=>Math.min(1,Math.max(0,(s-SIM_LO)/(SIM_HI-SIM_LO)));\nconst CURSE={line:{t:'קו אחד',d:'בלי להרים את האצבע'},three:{t:'3 קווים',d:'רק שלושה קווים'},mirror:{t:'מראה',d:'הקו יוצא הפוך מהאצבע'},white:{t:'מכחול לבן',d:'הקו לא נראה בזמן הציור'},time:{t:'5 שניות',d:'מהנגיעה הראשונה'}};\nCURSE.half=CURSE.white;\nObject.assign(CURSE,{straight:{t:'קווים ישרים',d:'כל קו נמתח לקו ישר'},flip:{t:'הפוך',d:'הקו יוצא הפוך למעלה־למטה'},rotate:{t:'לוח מסתובב',d:'הלוח מסתובב בזמן הציור'},shaky:{t:'יד רועדת',d:'הקו יוצא רועד'},dots:{t:'נקודות בלבד',d:'רק נגיעות, בלי למשוך'},fade:{t:'קו נעלם',d:'כל קו נעלם אחרי 2 שניות'},tiny:{t:'לוח זעיר',d:'מציירים רק בריבוע הקטן'},fat:{t:'מכחול שמן',d:'קו עבה מאוד'}});\nconst maxPts=(l,k)=>Math.round(BASE[l]*(1+sizeBonus(k)));\n\n/* ---------- רשת עצבית ---------- */\nlet S={cats:[],ex:[],rounds:0,updated:0};// cats:[{w}] ex:[{c,d}]\nlet net=null;\nfunction randn(){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);}\nfunction newNet(){const W1=new Float32Array(H*IN),s=Math.sqrt(2/IN);for(let i=0;i<W1.length;i++)W1[i]=randn()*s;net={W1,b1:new Float32Array(H),W2:[],b2:[]};for(let k=0;k<S.cats.length;k++)addOut();}\nfunction addOut(){const w=new Float32Array(H),s=Math.sqrt(1/H);for(let j=0;j<H;j++)w[j]=randn()*s;net.W2.push(w);net.b2.push(0);}\nfunction toX(d,dx=0,dy=0){const x=new Float32Array(IN),nz=[];for(let y=0;y<N;y++){const sy=y-dy;if(sy<0||sy>=N)continue;for(let xx=0;xx<N;xx++){const sx=xx-dx;if(sx<0||sx>=N)continue;const v=d[sy*N+sx];if(v){const i=y*N+xx;x[i]=v/15;nz.push(i);}}}return {x,nz};}\nfunction forward(X){const {x,nz}=X,h=new Float32Array(H),W1=net.W1;for(let j=0;j<H;j++){let s=net.b1[j];const o=j*IN;for(let t=0;t<nz.length;t++){const i=nz[t];s+=W1[o+i]*x[i];}h[j]=s>0?s:0;}\n const K=net.W2.length,p=new Float32Array(K);let m=-1e9;for(let k=0;k<K;k++){let s=net.b2[k];const w=net.W2[k];for(let j=0;j<H;j++)s+=w[j]*h[j];p[k]=s;if(s>m)m=s;}\n let sum=0;for(let k=0;k<K;k++){p[k]=Math.exp(p[k]-m);sum+=p[k];}for(let k=0;k<K;k++)p[k]/=sum;return {h,p};}\nfunction step(X,y){const {h,p}=forward(X),K=p.length,dh=new Float32Array(H);\n for(let k=0;k<K;k++){const g=p[k]-(k===y?1:0),w=net.W2[k];for(let j=0;j<H;j++){dh[j]+=g*w[j];w[j]-=LR*g*h[j];}net.b2[k]-=LR*g;}\n const {x,nz}=X,W1=net.W1;for(let j=0;j<H;j++){if(h[j]<=0)continue;const g=dh[j];if(!g)continue;const o=j*IN;for(let t=0;t<nz.length;t++){const i=nz[t];W1[o+i]-=LR*g*x[i];}net.b1[j]-=LR*g;}\n return -Math.log(p[y]+1e-9);}\nconst argmax=p=>{let b=0;for(let i=1;i<p.length;i++)if(p[i]>p[b])b=i;return b;};\nconst byCat=()=>{const b=S.cats.map(()=>[]);S.ex.forEach(e=>b[e.c]&&b[e.c].push(e));return b;};\nconst counts=()=>byCat().map(a=>a.length);\nconst readyWords=()=>counts().filter(n=>n>=MIN_EX).length;\nconst trainable=()=>counts().filter(n=>n>0).length>=2;\n// אימון: הזזה קטנה + הטיה אקראית עד 45° (בלי היפוכים)\nfunction aug(e){const k=(Math.random()*7)|0;e.t=e.t||[];const d=e.t[k]||(e.t[k]=tf8(e.d,SIM_TF[k]));return toX(d,((Math.random()*5)|0)-2,((Math.random()*5)|0)-2);}\nfunction evalAcc(){if(!S.ex.length)return 0;let ok=0;for(const e of S.ex)if(argmax(forward(toX(e.d)).p)===e.c)ok++;return ok/S.ex.length;}\nfunction catIndex(w){return S.cats.findIndex(c=>c.w===w);}\nfunction ensureCat(w){let k=catIndex(w);if(k<0){S.cats.push({w});addOut();k=S.cats.length-1;}return k;}\n\n/* אימון ברקע */\nconst T={on:false,start:0,best:Infinity,bestT:0,acc:0,loss:1,lastAcc:0,done:false};\nfunction kickTrain(){if(!trainable()){T.on=false;T.done=false;paintTrain();return;}T.done=false;if(T.on)return;T.on=true;T.start=performance.now();T.best=Infinity;T.bestT=T.start;T.loss=1;requestAnimationFrame(trainFrame);paintTrain();}\nfunction trainFrame(){\n if(!T.on)return;\n const b=byCat(),ks=[];b.forEach((a,k)=>{if(a.length)ks.push(k);});\n const t0=performance.now();let n=0,ls=0;\n while(performance.now()-t0<14){const a=b[ks[(Math.random()*ks.length)|0]],e=a[(Math.random()*a.length)|0];ls+=step(aug(e),e.c);n++;}\n S.rounds+=n;T.loss=T.loss*0.9+(ls/n)*0.1;\n const now=performance.now();\n if(now-T.lastAcc>700){T.lastAcc=now;T.acc=evalAcc();\n  if(T.loss<T.best-Math.max(T.best*0.03,0.01)){T.best=T.loss;T.bestT=now;}\n  paintTrain();\n  const good=T.acc>=0.98&&T.loss<0.06;\n  if(now-T.start>1500&&(good||now-T.bestT>(T.acc>=0.98?2500:7000)||now-T.start>25000)){T.on=false;T.done=true;paintTrain();dirty();return;}\n }\n requestAnimationFrame(trainFrame);\n}\nfunction paintTrain(){\n const el=$('#wStatus');\n if(cur.view==='vWord'){\n  const n=counts()[catIndex(cur.word)]||0;\n  el.className='status';\n  if(!trainable()){el.textContent=S.cats.length<=1&&n?'הוסיפו מילה שנייה – כדי שהמוח ילמד להבדיל ביניהן':(n?'':'ציירו את המילה ולחצו \"שמור בזיכרון\"');}\n  else if(T.on){el.innerHTML=`<span class=\"pulse\"><i></i><i></i><i></i></span>המוח לומד… מזהה נכון ${Math.round(T.acc*100)}%`;}\n  else if(n){el.classList.add('good');el.textContent=`המוח למד · מזהה נכון ${Math.round(evalAcc()*100)}% מהציורים`;}\n  else el.textContent='ציירו את המילה ולחצו \"שמור בזיכרון\"';\n  paintWordActs();\n }\n if(cur.view==='vRoom')paintRoomHead();\n}\n\n/* ---------- שמירה וסנכרון ---------- */\nconst HEX='0123456789abcdef';\nfunction dToStr(d){let s='';for(let i=0;i<d.length;i++)s+=HEX[d[i]];return s;}\nfunction strToD(s){const d=new Uint8Array(IN);for(let i=0;i<IN;i++)d[i]=parseInt(s[i],16)||0;return d;}\nfunction f2b(a){const u=new Uint8Array(a.buffer,a.byteOffset,a.byteLength);let s='';for(let i=0;i<u.length;i+=0x8000)s+=String.fromCharCode.apply(null,u.subarray(i,i+0x8000));return btoa(s);}\nfunction b2f(b){const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return new Float32Array(u.buffer);}\nfunction netJSON(){return JSON.stringify({H,W1:f2b(net.W1),b1:f2b(net.b1),W2:net.W2.map(f2b),b2:Array.from(net.b2)});}\nfunction loadNet(s){const o=JSON.parse(s);if(o.H!==H||o.W2.length!==S.cats.length)return false;net={W1:b2f(o.W1),b1:b2f(o.b1),W2:o.W2.map(b2f),b2:o.b2.slice()};return true;}\nasync function zip(str){if(!window.CompressionStream)return 'P'+btoa(unescape(encodeURIComponent(str)));const cs=new Blob([str]).stream().pipeThrough(new CompressionStream('deflate-raw'));const u=new Uint8Array(await new Response(cs).arrayBuffer());let s='';for(let i=0;i<u.length;i+=0x8000)s+=String.fromCharCode.apply(null,u.subarray(i,i+0x8000));return 'Z'+btoa(s);}\nasync function unzip(b){if(!b)return '[]';if(b[0]==='P')return decodeURIComponent(escape(atob(b.slice(1))));const s=atob(b.slice(1)),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);const ds=new Blob([u]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return await new Response(ds).text();}\nfunction exJSON(){return JSON.stringify(S.ex.map(e=>e.L?[e.c,dToStr(e.d),e.L]:[e.c,dToStr(e.d)]));}\nfunction saveLocal(){if(DEMO)return;ls.set('brain',{pid:AUTH&&AUTH.id,cats:S.cats,ex:exJSON(),rounds:S.rounds,updated:S.updated,net:net?netJSON():null});}\nlet upT=null,upP=null,pendingUp=false;\nfunction dirty(){S.updated=Date.now();saveLocal();pendingUp=true;clearTimeout(upT);upT=setTimeout(upload,1800);}\nasync function upload(){\n if(!AUTH||!pendingUp)return;if(T.on){clearTimeout(upT);upT=setTimeout(upload,1500);return;}\n pendingUp=false;const c=counts();\n upP=api('brain',{method:'PUT',body:{cats:S.cats.map((x,i)=>({w:x.w,n:c[i]})),net:netJSON(),ex:await zip(exJSON()),rounds:S.rounds}}).then(()=>loadMine()).catch(e=>{pendingUp=true;toast('השמירה בשרת נכשלה – ננסה שוב');clearTimeout(upT);upT=setTimeout(upload,8000);});\n return upP;\n}\nasync function flushUpload(){clearTimeout(upT);while(T.on)await new Promise(r=>setTimeout(r,300));if(pendingUp)await upload();else if(upP)await upP;}\nasync function loadBrain(){\n const loc=ls.get('brain',null);let used=false;\n if(loc&&loc.pid===AUTH.id){S.cats=loc.cats;S.ex=JSON.parse(loc.ex).map(a=>({c:a[0],d:strToD(a[1]),L:a[2]||0}));S.rounds=loc.rounds;S.updated=loc.updated||0;if(!(loc.net&&loadNet(loc.net)))newNet();used=true;}\n try{const {brain}=await api('brain');\n  if(brain&&(!used||brain.updated>S.updated)){\n   S.cats=JSON.parse(brain.cats).map(c=>({w:c.w}));S.ex=JSON.parse(await unzip(brain.ex)).map(a=>({c:a[0],d:strToD(a[1]),L:a[2]||0}));S.rounds=brain.rounds;S.updated=brain.updated;\n   if(!(brain.net&&loadNet(brain.net)))newNet();saveLocal();used=true;\n  }else if(used&&(!brain||brain.updated<S.updated)){pendingUp=true;upload();}\n }catch(e){}\n if(!used){S={cats:[],ex:[],rounds:0,updated:0};newNet();}\n}\n\n/* ---------- לוח ציור ---------- */\nconst pad=document.createElement('canvas');pad.id='pad';pad.width=pad.height=280;\nconst pctx=pad.getContext('2d',{willReadFrequently:true});\nconst padWrap=document.createElement('div');padWrap.className='sheetPad';\nconst padHint=document.createElement('div');padHint.className='padHint';padWrap.append(pad,padHint);\nconst blind=document.createElement('div');blind.className='blind hide';blind.innerHTML='<span>המכחול לבן – ציירו מהזיכרון</span>';\nconst ghost=document.createElement('canvas');ghost.width=ghost.height=280;ghost.className='ghost hide';const gctx=ghost.getContext('2d');\nconst tinyBox=document.createElement('div');tinyBox.className='tinyWrap hide';tinyBox.innerHTML='<i></i>';\npadWrap.append(blind,ghost,tinyBox);\n/* אנימציית למידה: הפיקסלים של הציור זורמים אל המוח */\nconst fx=document.createElement('div');fx.className='learnFx hide';\nfx.innerHTML='<canvas></canvas><svg class=\"fxBrain\" viewBox=\"0 0 64 64\" aria-hidden=\"true\"><use href=\"#mascotBig\"/></svg><div class=\"fxTxt\" role=\"status\"></div>';\npadWrap.append(fx);\nlet fxRun=0;\nfunction learnFx(d,word){\n const run=++fxRun,cv=fx.querySelector('canvas'),txt=fx.querySelector('.fxTxt');\n const W=padWrap.clientWidth||280,dpr=Math.min(2,devicePixelRatio||1);cv.width=cv.height=Math.round(W*dpr);\n const g=cv.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);\n const cs=W/N,cx=W/2,cy=W*.42,R=W*.13,cells=[];\n for(let i=0;i<IN;i++)if(d[i]>2){const x=i%N,y=(i/N)|0;cells.push({x:x*cs,y:y*cs,v:d[i]/15,del:Math.random()*320,tx:cx+(Math.random()-.5)*R*1.6,ty:cy+(Math.random()-.5)*R*1.3});}\n fx.className='learnFx';txt.textContent='המוח לומד…';\n const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;\n const t0=performance.now(),SCAN=480,FLY=900,MIN=1500,MAX=6000;\n const ease=t=>1-Math.pow(1-t,3),easeIn=t=>t*t*t;\n let finished=false;\n function finish(){if(finished||run!==fxRun)return;finished=true;fx.classList.add('done');fx.classList.remove('pulse');txt.textContent=word?`נשמר: \"${word}\" ✓`:'נשמר בזיכרון ✓';\n  setTimeout(()=>{if(run!==fxRun)return;fx.classList.add('out');setTimeout(()=>{if(run===fxRun)fx.className='learnFx hide';},260);},650);}\n fx.onclick=()=>{if(performance.now()-t0>SCAN)finish();};\n function frame(now){\n  if(run!==fxRun)return;const t=now-t0;g.clearRect(0,0,W,W);\n  g.strokeStyle='rgba(255,255,255,.07)';g.lineWidth=1;\n  for(let k=1;k<N;k++){g.beginPath();g.moveTo(k*cs,0);g.lineTo(k*cs,W);g.moveTo(0,k*cs);g.lineTo(W,k*cs);g.stroke();}\n  if(!reduce&&t<SCAN){\n   const sy=t/SCAN*W;\n   for(const c of cells)if(c.y<sy){g.fillStyle=`rgba(255,227,214,${.25+c.v*.75})`;g.fillRect(c.x+1,c.y+1,cs-2,cs-2);}\n   const grd=g.createLinearGradient(0,sy-28,0,sy);grd.addColorStop(0,'rgba(226,70,31,0)');grd.addColorStop(1,'rgba(226,70,31,.55)');g.fillStyle=grd;g.fillRect(0,sy-28,W,28);\n   g.fillStyle='#E2461F';g.fillRect(0,sy-2,W,2);\n  }else{\n   if(!fx.classList.contains('b')){fx.classList.add('b');}\n   const tf=reduce?FLY:t-SCAN;let left=0;\n   for(const c of cells){const p=Math.min(1,Math.max(0,(tf-c.del)/(FLY-320)));if(p<1)left++;\n    const e=easeIn(p),x=c.x+(c.tx-c.x)*e,y=c.y+(c.ty-c.y)*e,sz=(cs-2)*(1-e*.75);\n    if(p>=1)continue;g.fillStyle=p<.5?`rgba(255,227,214,${.3+c.v*.7})`:`rgba(${Math.round(255-30*p)},${Math.round(227-150*p)},${Math.round(214-180*p)},${1-p*.4})`;\n    g.fillRect(x+(cs-sz)/2,y+(cs-sz)/2,sz,sz);}\n   if(!left&&!finished){fx.classList.add('pulse');\n    const k=(t/140)|0;for(let j=0;j<5;j++){const a=(k*0.7+j*1.256)%(Math.PI*2),r=R*1.55;g.fillStyle=['#E2461F','#6343D6','#1A8E58','#B87400','#F6D36B'][j];g.beginPath();g.arc(cx+Math.cos(a+t/420)*r,cy+Math.sin(a+t/420)*r*.85,3,0,7);g.fill();}\n    if((t>MIN&&!T.on)||t>MAX)finish();}\n  }\n  if(!finished||!fx.classList.contains('out'))requestAnimationFrame(frame);\n }\n requestAnimationFrame(frame);\n}\nconst TINY=[93,93,187,187];\nlet drawing=false,last=null,hasInk=false,tool='pen',padLocked=false,onStroke=null,curse=null,strokes=0,curseT=0,curseTimer=0,strokeStart=null,strokeSnap=null,rotA=0,rotRAF=0,fadeRAF=0,inkLen=0,lastL=0,bx0=1e9,by0=1e9,bx1=-1e9,by1=-1e9;\nfunction clearPad(){inkLen=0;lastL=0;bx0=by0=1e9;bx1=by1=-1e9;pctx.fillStyle='#fff';pctx.fillRect(0,0,280,280);gctx.clearRect(0,0,280,280);hasInk=false;padHint.textContent='ציירו כאן';strokes=0;curseT=0;clearInterval(curseTimer);if(curse)padLocked=false;paintCurse();}\nfunction pos(e){\n const r=pad.getBoundingClientRect();let x,y;\n if(curse==='rotate'){const cx=r.left+r.width/2,cy=r.top+r.height/2,ps=pad.offsetWidth||r.width,dx=e.clientX-cx,dy=e.clientY-cy,c=Math.cos(-rotA),s=Math.sin(-rotA);x=((dx*c-dy*s)/ps+.5)*280;y=((dx*s+dy*c)/ps+.5)*280;}\n else{x=(e.clientX-r.left)/r.width*280;y=(e.clientY-r.top)/r.height*280;}\n if(curse==='mirror')x=280-x;\n if(curse==='flip')y=280-y;\n if(curse==='shaky'){x+=(Math.random()-.5)*16;y+=(Math.random()-.5)*16;}\n return {x,y};\n}\nfunction startCurseFx(){\n cancelAnimationFrame(rotRAF);cancelAnimationFrame(fadeRAF);rotA=0;pad.style.transform='';ghost.style.transform='';\n blind.classList.toggle('hide',!(curse==='white'||curse==='half'||curse==='fade'));blind.querySelector('span').textContent=curse==='fade'?'':'המכחול לבן – ציירו מהזיכרון';\n ghost.classList.toggle('hide',curse!=='fade');tinyBox.classList.toggle('hide',curse!=='tiny');\n if(curse==='rotate'){let t0=performance.now();const f=t=>{if(curse!=='rotate'){pad.style.transform='';return;}rotA=((t-t0)/1000)*0.5;pad.style.transform=`rotate(${rotA}rad)`;rotRAF=requestAnimationFrame(f);};rotRAF=requestAnimationFrame(f);}\n if(curse==='fade'){const f=()=>{if(curse!=='fade')return;gctx.globalCompositeOperation='destination-out';gctx.fillStyle='rgba(0,0,0,.03)';gctx.fillRect(0,0,280,280);gctx.globalCompositeOperation='source-over';fadeRAF=requestAnimationFrame(f);};fadeRAF=requestAnimationFrame(f);}\n}\nfunction paintCurse(){\n const el=$('#dCurse');if(!el)return;\n if(!curse){el.innerHTML=MODE==='ink'&&cur.ch?`<b>פחות דיו = יותר נקודות</b><span></span><i class=\"num\"><bdi>${cur.ch.min}–${cur.ch.max}</bdi></i>`:'';if(MODE==='ink')paintLive();return;}\n const c=CURSE[curse]||{t:'',d:''};let st='';\n if(curse==='line')st=strokes?'השתמשת בקו':'';\n if(curse==='three')st=`${strokes}/3 קווים`;\n if(curse==='time')st=curseT?`${Math.max(0,Math.ceil((curseT-Date.now())/1000))} שניות`:'השעון מתחיל בנגיעה';\n el.innerHTML=`<b></b><span></span>${st?`<i class=\"num\"></i>`:''}`;el.querySelector('b').textContent=c.t;el.querySelector('span').textContent=c.d;if(st)el.querySelector('i').textContent=st;\n}\nfunction curseBlocks(){\n if(!curse)return false;\n if((curse==='line'&&strokes>=1)||(curse==='three'&&strokes>=3)){toast('נגמרו הקווים – אפשר לנקות ולהתחיל מחדש');return true;}\n if(curse==='time'&&curseT&&Date.now()>curseT){toast('נגמר הזמן – אפשר לנקות ולהתחיל מחדש');return true;}\n return false;\n}\nfunction seg(a,b){\n const er=tool==='eraser',w=er?40:(curse==='fat'?46:18);\n const draw=ctx=>{ctx.strokeStyle=er?'#fff':'#1F2440';ctx.lineWidth=w;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x+.01,b.y);ctx.stroke();};\n pctx.save();if(curse==='tiny'){pctx.beginPath();pctx.rect(TINY[0],TINY[1],TINY[2]-TINY[0],TINY[3]-TINY[1]);pctx.clip();}draw(pctx);pctx.restore();\n if(curse==='fade'){if(er){gctx.save();gctx.globalCompositeOperation='destination-out';draw(gctx);gctx.restore();}else draw(gctx);}\n if(!er){hasInk=true;padHint.textContent='';inkLen+=Math.hypot(b.x-a.x,b.y-a.y);for(const q of [a,b]){bx0=Math.min(bx0,q.x);by0=Math.min(by0,q.y);bx1=Math.max(bx1,q.x);by1=Math.max(by1,q.y);}if(MODE==='ink'&&cur.view==='vDraw')paintLive();}\n}\n/* הקלטת ציור באתגר: [סוג, x, y, זמן] לכל נקודה. סוג: 0 עט, 1 מחק, 2 נקודה, 3 ניקוי */\nlet REC=[],recT0=0;\nfunction recPush(k,p){if(cur.view!=='vDraw'||REC.length>=16000)return;const t=Date.now(),dt=recT0?Math.min(255,Math.round((t-recT0)/10)):0;recT0=t;\n REC.push(k,p?Math.max(0,Math.min(255,Math.round(p.x/280*255))):0,p?Math.max(0,Math.min(255,Math.round(p.y/280*255))):0,dt);}\nfunction recB64(){let s='';for(const v of REC)s+=String.fromCharCode(v);return btoa(s);}\npad.addEventListener('pointerdown',e=>{if(padLocked||curseBlocks())return;pad.setPointerCapture(e.pointerId);drawing=true;strokes++;recPush(tool==='eraser'?1:0,pos(e));\n if(curse==='time'&&!curseT){curseT=Date.now()+5000;clearInterval(curseTimer);curseTimer=setInterval(()=>{paintCurse();if(Date.now()>curseT){clearInterval(curseTimer);drawing=false;padLocked=true;paintCurse();}},250);}\n last=pos(e);strokeStart=last;if(curse==='straight')strokeSnap=pctx.getImageData(0,0,280,280);seg(last,last);paintCurse();});\npad.addEventListener('pointermove',e=>{if(!drawing||padLocked||curse==='dots')return;const p=pos(e);recPush(2,p);\n if(curse==='straight'){pctx.putImageData(strokeSnap,0,0);seg(strokeStart,p);}else seg(last,p);\n last=p;if(onStroke)onStroke(false);});\nconst endDraw=()=>{if(!drawing)return;drawing=false;if(onStroke)onStroke(true);};\npad.addEventListener('pointerup',endDraw);pad.addEventListener('pointercancel',endDraw);\nconst tmp=document.createElement('canvas');tmp.width=tmp.height=N;const tctx=tmp.getContext('2d',{willReadFrequently:true});\nfunction grabPad(){\n if(!hasInk)return null;const img=pctx.getImageData(0,0,280,280).data;let x0=280,y0=280,x1=-1,y1=-1;\n for(let y=0;y<280;y++)for(let x=0;x<280;x++)if(img[(y*280+x)*4]<128){if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y;}\n if(x1<0)return null;const w=x1-x0+1,h=y1-y0+1,s=20/Math.max(w,h),dw=w*s,dh=h*s;lastL=Math.round(liveL()*100)/100;\n tctx.fillStyle='#fff';tctx.fillRect(0,0,N,N);tctx.imageSmoothingEnabled=true;tctx.imageSmoothingQuality='high';tctx.drawImage(pad,x0,y0,w,h,(N-dw)/2,(N-dh)/2,dw,dh);\n const t=tctx.getImageData(0,0,N,N).data,d=new Uint8Array(IN);for(let i=0;i<IN;i++)d[i]=Math.round((255-t[i*4])/255*15);return d;\n}\nfunction thumb(d,c){c=c||document.createElement('canvas');c.width=c.height=N;const x=c.getContext('2d'),im=x.createImageData(N,N);\n for(let i=0;i<IN;i++){const a=d[i]/15;im.data[i*4]=255-a*(255-31);im.data[i*4+1]=255-a*(255-36);im.data[i*4+2]=255-a*(255-64);im.data[i*4+3]=255;}x.putImageData(im,0,0);return c;}\nfunction setTool(t){tool=t;$$('[data-tool]').forEach(b=>b.classList.toggle('sel',b.dataset.tool===t));}\n$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));\n$$('[data-clear]').forEach(b=>b.onclick=()=>{recPush(3,null);clearPad();if(onStroke)onStroke(true);});\nfunction mountPad(view){\n const slot=$(`#${view} [data-pad]`);if(!slot)return;slot.appendChild(padWrap);curse=MODE!=='ink'&&view==='vDraw'&&cur.ch?cur.ch.curse||null:null;startCurseFx();clearPad();setTool('pen');padLocked=false;\n requestAnimationFrame(sizePad);\n}\nfunction sizePad(){const s=padWrap.parentElement;if(!s)return;const r=s.getBoundingClientRect();const ps=Math.max(150,Math.floor(Math.min(r.width,r.height-12)));padWrap.style.setProperty('--ps',ps+'px');}\naddEventListener('resize',()=>requestAnimationFrame(sizePad));\n\n/* ---------- ניווט ---------- */\nconst cur={view:'vRoom',word:null,lvl:1,sq:'open',ch:null,stack:[]};\nconst FOCUS=new Set(['vWord','vTest','vDraw']);\nfunction go(v,push=true){\n if(push&&cur.view!==v&&FOCUS.has(v))cur.stack.push(cur.view);\n cur.view=v;$$('.view').forEach(s=>s.classList.toggle('on',s.id===v));\n document.body.classList.toggle('focus',FOCUS.has(v)||v==='vLogin');\n $$('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.v===v));\n onStroke=null;\n if(v==='vRoom')renderRoom();\n if(v==='vWord'){mountPad('vWord');renderWord();}\n if(v==='vTest'){mountPad('vTest');renderTest();}\n if(v==='vSquare')renderSquare();\n if(v==='vDraw'){mountPad('vDraw');renderDraw();}\n if(v==='vLeaders')renderLeaders();\n}\n$$('#nav button').forEach(b=>b.onclick=()=>{cur.stack=[];go(b.dataset.v,false);});\n$$('[data-back]').forEach(b=>b.onclick=()=>go(cur.stack.pop()||'vRoom',false));\n\n/* ---------- טוסט ---------- */\nconst sgn=n=>`<bdi>${n>0?'+':''}${n}</bdi>`;\n['focusout','resize'].forEach(ev=>addEventListener(ev,()=>setTimeout(()=>{window.scrollTo(0,0);$('#app').scrollTop=0;$('main').scrollTop=0;$$('.view').forEach(v=>v.scrollTop=0);},60)));\nlet askR=null;\nfunction ask(t,p,yes){return new Promise(r=>{askR=r;$('#askT').textContent=t;$('#askP').textContent=p||'';$('#askYes').textContent=yes||'אישור';openSheet('#shAsk');});}\nfunction askDone(v){if(askR){const r=askR;askR=null;closeSheets();r(v);}}\n$('#askYes').onclick=()=>askDone(true);$('#askNo').onclick=()=>askDone(false);\nlet toastT=0;function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toastT);toastT=setTimeout(()=>t.classList.remove('on'),2600);}\n\n/* ---------- המוח שלי ---------- */\nfunction mascotDots(svg,n){\n const spots=[[24,29],[40,29],[32,41],[18,24],[46,24],[21,40],[43,40],[28,20],[36,20],[26,35],[38,35],[32,28],[15,32],[49,32],[32,17]];\n const cols=['#E2461F','#6343D6','#1A8E58','#B87400'];\n let h='<use href=\"#mascotBody\"/>';\n spots.forEach((p,i)=>{h+=`<circle cx=\"${p[0]}\" cy=\"${p[1]}\" r=\"${i<n?2.6:1.6}\" fill=\"${i<n?cols[i%4]:'#E3C9BC'}\"/>`;});\n svg.innerHTML=h;\n}\nfunction paintRoomHead(){\n const c=counts(),words=S.cats.length,ready=readyWords();\n mascotDots($('#roomMascot'),ready);\n $('#rTitle').textContent=words?`המוח מכיר ${words} מילים`:'המוח שלך ריק';\n $('#rSub').textContent=!words?'בחרו מילה מהמאגר והתחילו לצייר':SOLO?(T.on?'המוח לומד…':`${ready} מילים במוח`):ready<MIN_WORDS?`${ready} מוכנות · עוד ${MIN_WORDS-ready} עד שאפשר לאתגר`:T.on?'המוח לומד…':`${ready} מילים מוכנות לאתגר`;\n $('#rTest').disabled=!(trainable()&&S.rounds>0);\n}\nlet myOpen=new Map();// word -> challenge id\nasync function loadMine(){try{const {challenges}=await api('mine');myOpen=new Map(challenges.filter(c=>c.status==='open').map(c=>[c.word,c.id]));mineCache=challenges;if(cur.view==='vRoom')renderMyWords();if(cur.view==='vWord')paintWordActs();if(cur.view==='vSquare'&&cur.sq==='mine')renderSquareList();}catch(e){}}\nlet mineCache=[];\nfunction meter(n,lv){let h=`<span class=\"meter lv${lv}\">`;for(let i=0;i<MAX_EX;i++)h+=`<i class=\"${i<n?'f':''}\"></i>`;return h+'</span>';}\nfunction renderMyWords(){\n const box=$('#myWords'),n=S.cats.length;box.disabled=!n;\n if(!n){box.innerHTML='<span class=\"peek\">המילים שתלמדו יופיעו כאן</span>';return;}\n const last=S.cats.slice(-4).reverse().map(x=>x.w).join(' · ');\n box.innerHTML=`<b>המילים שלי</b><span class=\"cnt num\">${n}</span><span class=\"peek\"></span><svg class=\"ic\"><use href=\"#i-search\"/></svg>`;box.querySelector('.peek').textContent=last;\n}\n$('#myWords').onclick=()=>{if(!S.cats.length)return;$('#mineQ').value='';renderMine();openSheet('#shMine');};\n$('#mineQ').addEventListener('input',renderMine);\nfunction renderMine(){\n const q=$('#mineQ').value.trim(),c=counts(),box=$('#mineList');box.innerHTML='';\n const items=S.cats.map((x,i)=>({w:x.w,n:c[i]})).filter(o=>!q||o.w.includes(q)).sort((a,b)=>a.w.localeCompare(b.w,'he'));\n $('#mineTitle').textContent=`המילים שלי · ${S.cats.length}`;\n if(!items.length){box.innerHTML='<div class=\"empty\"><b>אין מילה כזאת במוח</b><span>אפשר להוסיף אותה מהמאגר</span></div>';return;}\n let letter='';const frag=document.createDocumentFragment();\n items.forEach(o=>{const lv=LVL.get(o.w),f=o.w[0];\n  if(f!==letter&&!q){letter=f;const h=document.createElement('div');h.className='letterHd';h.textContent=f;frag.appendChild(h);}\n  const b=document.createElement('button');b.className='wr in lv'+lv;\n  b.innerHTML=`${myOpen.has(o.w)?'<svg class=\"ic\" style=\"color:var(--accent);width:18px;height:18px\"><use href=\"#i-flag\"/></svg>':''}<b></b><span class=\"st\">${meter(o.n,lv)}<span class=\"num\">${o.n}/${MAX_EX}</span></span>`;\n  b.querySelector('b').textContent=o.w;b.onclick=()=>{closeSheets();openWord(o.w);};frag.appendChild(b);});\n box.appendChild(frag);\n}\nfunction renderList(){\n const q=$('#q').value.trim(),box=$('#wordList'),c=counts();box.innerHTML='';\n let items=q?[1,2,3].flatMap(l=>WORDS[l].filter(w=>w.includes(q)).map(w=>[w,l])).concat(S.cats.filter(x=>!LVL.has(x.w)&&x.w.includes(q)).map(x=>[x.w,4])):WORDS[cur.lvl].map(w=>[w,cur.lvl]);\n if(q&&!items.some(i=>i[0]===q)){const a=document.createElement('button');a.className='addBtn';a.innerHTML='<svg class=\"ic\"><use href=\"#i-plus\"/></svg><span></span>';a.lastChild.textContent=`הוסף \"${q}\" כמילה משלי`;a.onclick=()=>addFree(q);\n  if(!items.length){box.innerHTML='<div class=\"empty\"><b>המילה לא במאגר</b><span>אפשר להוסיף אותה כמילה משלי</span></div>';box.firstChild.appendChild(a);return;}\n  box.appendChild(a);}\n if(q)items.sort((a,b)=>a[0].localeCompare(b[0],'he'));\n const frag=document.createDocumentFragment();let letter='';\n items.forEach(([w,l])=>{if(!q&&w[0]!==letter){letter=w[0];const h=document.createElement('div');h.className='letterHd';h.textContent=letter;frag.appendChild(h);}\n  const k=catIndex(w),n=k>=0?c[k]:0,b=document.createElement('button');b.className='wr lv'+l+(k>=0?' in':'');\n  b.innerHTML=`<b></b>${q?`<span class=\"tag\">${LVNAME[l]}</span>`:''}${k>=0?`<span class=\"st\">${meter(n,l)}<span class=\"num\">${n}/${MAX_EX}</span></span>`:'<span class=\"plus\"><svg class=\"ic\"><use href=\"#i-plus\"/></svg></span>'}`;\n  b.querySelector('b').textContent=w;b.onclick=()=>openWord(w);frag.appendChild(b);});\n box.appendChild(frag);\n}\nfunction renderRoom(){paintRoomHead();renderMyWords();renderList();$$('#lvSeg button').forEach(b=>b.classList.toggle('on',+b.dataset.l===cur.lvl));}\n$$('#lvSeg button').forEach(b=>b.onclick=()=>{cur.lvl=+b.dataset.l;$('#q').value='';renderRoom();$('#wordList').scrollTop=0;});\n$('#q').addEventListener('input',renderList);\n$('#rnd').onclick=()=>{const pool=WORDS[cur.lvl].filter(w=>catIndex(w)<0);const list=pool.length?pool:WORDS[cur.lvl];openWord(list[(Math.random()*list.length)|0]);};\n$('#rTest').onclick=()=>go('vTest');\nfunction addFree(w){\n w=String(w||'').trim();const e=wordProblem(w);\n if(e){$('#addQ').value=w;$('#addErr').textContent=e;if(!$('#shAdd').classList.contains('on'))openSheet('#shAdd');return;}\n closeSheets();$('#q').value='';\n if(LVL.has(w)){toast('המילה כבר במאגר');openWord(w);return;}\n openWord(w);\n}\n$('#addW').onclick=()=>{$('#addQ').value=$('#q').value.trim();$('#addErr').textContent='';openSheet('#shAdd');setTimeout(()=>$('#addQ').focus(),250);};\n$('#addQ').addEventListener('input',()=>{$('#addErr').textContent='';});\n$('#addQ').addEventListener('keydown',e=>{if(e.key==='Enter')addFree($('#addQ').value);});\n$('#addYes').onclick=()=>addFree($('#addQ').value);\n$('#addNo').onclick=closeSheets;\n\n/* ---------- אימון מילה ---------- */\nfunction openWord(w){cur.word=w;go('vWord');}\nfunction renderWord(){\n const w=cur.word,lv=LVL.get(w);$('#vWord').className='view on lv'+lv;\n $('#wTitle').textContent=w;const kn=catIndex(w),nn=kn>=0?counts()[kn]:0;$('#wSub').innerHTML=`<span class=\"tag\">${LVNAME[lv]} · ${BASE[lv]} נק׳${nn?` · <bdi>×${riskMult(nn)}</bdi>`:''}</span>`;\n renderSlots();paintTrain();\n}\nfunction renderSlots(){\n const k=catIndex(cur.word),exs=k>=0?byCat()[k]:[],box=$('#slots');box.innerHTML='';\n for(let i=0;i<MAX_EX;i++){const b=document.createElement('button');const e=exs[i];\n  if(e){b.className='f';b.appendChild(thumb(e.d));b.setAttribute('aria-label','הגדלת ציור '+(i+1));b.onclick=()=>openEx(exs,i);}\n  else{b.className=i<MIN_EX?'min':'';b.setAttribute('aria-label','מקום פנוי');b.disabled=true;}\n  box.appendChild(b);}\n $('#wDel').classList.toggle('hide',k<0);\n}\nfunction paintWordActs(){\n if(cur.view!=='vWord')return;\n const k=catIndex(cur.word),n=k>=0?counts()[k]:0,ready=readyWords(),pub=myOpen.has(cur.word);\n const solved=mineCache.find(c=>c.word===cur.word&&c.status==='solved');\n const save=$('#wSave');save.disabled=n>=MAX_EX;save.innerHTML=n>=MAX_EX?'המילה מלאה · 10/10':'<svg class=\"ic\"><use href=\"#i-check\"/></svg>שמור בזיכרון';\n const t=$('#wTest');t.disabled=n<MIN_EX||!trainable();t.classList.toggle('lit',!t.disabled);\n const p=$('#wPub');\n if(solved&&!pub){p.className='btn';p.style.color='';p.disabled=true;p.innerHTML=`<svg class=\"ic\"><use href=\"#i-check\"/></svg>נפתרה – לא לפרסום`;}\n else if(pub){p.disabled=false;p.className='btn';p.style.color='var(--accent)';p.innerHTML='<svg class=\"ic\"><use href=\"#i-flag\"/></svg>באתגר · הסרה';}\n else{p.className='btn';p.style.color='';p.innerHTML=`<svg class=\"ic\"><use href=\"#i-flag\"/></svg>${n<MIN_EX?'פרסום · ציירו קודם':ready<MIN_WORDS?`פרסום · ${ready}/${MIN_WORDS} מילים`:'פרסם אתגר'}`;p.disabled=n<MIN_EX||ready<MIN_WORDS||T.on;if(!p.disabled)p.classList.add('dark');}\n}\n$('#wSave').onclick=()=>{\n const d=grabPad();if(!d){toast('הלוח ריק – ציירו קודם');return;}\n const k=ensureCat(cur.word);if(byCat()[k].length>=MAX_EX)return;\n S.ex.push({c:k,d,L:lastL});learnFx(d);clearPad();renderWord();dirty();kickTrain();\n const n=byCat()[k].length;if(n===1&&readyWords()===MIN_WORDS&&!SOLO)setTimeout(()=>toast('5 מילים במוח! עכשיו אפשר לפרסם אתגרים'),1800);\n};\n/* הגדלת ציור שמור */\nfunction bigDraw(cv,d){\n // הגדלה חדה: אינטרפולציה חלקה + סף רך, כדי שהקו ייראה כמו קו ולא כמו כתם מטושטש\n const x=cv.getContext('2d'),W=cv.width,im=x.createImageData(W,W),sc=28/W;\n for(let Y=0;Y<W;Y++){const fy=Math.max(0,Math.min(27,(Y+.5)*sc-.5)),y0=Math.floor(fy),y1=Math.min(27,y0+1),ty=fy-y0;\n  for(let X=0;X<W;X++){const fx=Math.max(0,Math.min(27,(X+.5)*sc-.5)),x0=Math.floor(fx),x1=Math.min(27,x0+1),tx=fx-x0;\n   const v=((d[y0*28+x0]*(1-tx)+d[y0*28+x1]*tx)*(1-ty)+(d[y1*28+x0]*(1-tx)+d[y1*28+x1]*tx)*ty)/15;\n   let a=(v-.3)/.22;a=a<0?0:a>1?1:a*a*(3-2*a);const o=(Y*W+X)*4;\n   im.data[o]=Math.round(255-a*(255-0x1F));im.data[o+1]=Math.round(255-a*(255-0x24));im.data[o+2]=Math.round(255-a*(255-0x40));im.data[o+3]=255;}}\n x.putImageData(im,0,0);}\nlet exView=null;\nfunction openEx(list,i){exView={list,i};paintEx();openSheet('#shEx');}\nfunction paintEx(){const {list,i}=exView,e=list[i];if(!e){closeSheets();return;}\n $('#exT').textContent=`\"${S.cats[e.c].w}\" · ציור ${i+1} מתוך ${list.length}`;bigDraw($('#exC'),e.d);\n let t='';if(net&&trainable()){const p=forward(toX(e.d)).p,k=argmax(p);t=k===e.c?`המוח מזהה את הציור הזה ב־${Math.round(p[k]*100)}%`:`המוח חושב שזה \"${S.cats[k].w}\" (${Math.round(p[k]*100)}%)`;}\n $('#exP').textContent=t;$('#exPrev').disabled=i<=0;$('#exNext').disabled=i>=list.length-1;}\n$('#exPrev').onclick=()=>{if(exView.i>0){exView.i--;paintEx();}};\n$('#exNext').onclick=()=>{if(exView.i<exView.list.length-1){exView.i++;paintEx();}};\n$('#exClose').onclick=closeSheets;\n$('#exDel').onclick=async()=>{const e=exView.list[exView.i];closeSheets();await delExample(e);};\nasync function delExample(e){\n const k=e.c,n=byCat()[k].length;\n const warn=n===MIN_EX&&myOpen.has(S.cats[k].w)?'זה הציור האחרון של המילה – היא תימחק מהמוח והאתגר שלה ייסגר.':'';\n if(!await ask('למחוק את הציור הזה?',warn,'מחיקה'))return;\n S.ex.splice(S.ex.indexOf(e),1);\n if(!byCat()[k].length)removeCat(k);\n if(catIndex(cur.word)>=0)renderWord();else renderSlots();dirty();kickTrain();paintTrain();\n}\nfunction removeCat(k){S.cats.splice(k,1);net.W2.splice(k,1);net.b2.splice(k,1);S.ex=S.ex.filter(e=>e.c!==k).map(e=>({...e,c:e.c>k?e.c-1:e.c}));}\n$('#wDel').onclick=async()=>{const k=catIndex(cur.word);if(k<0)return;if(!await ask(`למחוק את \"${cur.word}\"?`,'כל הציורים של המילה יימחקו מהמוח.','מחיקה'))return;removeCat(k);dirty();kickTrain();go(cur.stack.pop()||'vRoom',false);};\n$('#wTest').onclick=()=>go('vTest');\n$('#wPub').onclick=async()=>{\n const b=$('#wPub'),w=cur.word;b.disabled=true;\n try{\n  if(myOpen.has(w)){await api('challenge/'+myOpen.get(w),{method:'DELETE'});myOpen.delete(w);toast('האתגר הוסר מהכיכר');}\n  else{b.innerHTML='שומר את המוח…';await flushUpload();await api('challenge',{method:'POST',body:{word:w}});toast(`\"${w}\" עלתה לכיכר – נודיע כשמישהו ינסה`);await loadMine();maybeAskPush();}\n }catch(e){toast(e.message);}\n paintWordActs();\n};\n\n/* ---------- בדיקה ---------- */\nlet predT=0;\nfunction renderTestWords(){\n const box=$('#tWords'),c=counts();box.innerHTML='';$('#tWordsN').textContent=S.cats.length;\n if(!S.cats.length){box.innerHTML='<span class=\"emptyLine\">עוד אין מילים במוח</span>';return;}\n S.cats.map((x,i)=>({w:x.w,n:c[i]})).sort((a,b)=>a.w.localeCompare(b.w,'he')).forEach(o=>{const d=document.createElement('span');d.className='mw lv'+LVL.get(o.w);d.innerHTML='<span></span><small class=\"num\"></small>';d.firstChild.textContent=o.w;d.lastChild.textContent=o.n+'/'+MAX_EX;box.appendChild(d);});\n}\n$('#tWordsBtn').onclick=e=>{e.stopPropagation();const p=$('#tWords'),open=p.classList.toggle('hide')===false;$('#tWordsBtn').setAttribute('aria-expanded',open);if(open)renderTestWords();};\ndocument.addEventListener('pointerdown',e=>{const p=$('#tWords');if(!p.classList.contains('hide')&&!p.contains(e.target)&&!$('#tWordsBtn').contains(e.target)){p.classList.add('hide');$('#tWordsBtn').setAttribute('aria-expanded',false);}});\nfunction renderTest(){\n $('#tWords').classList.add('hide');$('#tWordsBtn').setAttribute('aria-expanded',false);$('#tWordsN').textContent=S.cats.length;\n $('#tGuess').innerHTML='';$('#tBars').innerHTML='';\n onStroke=(end)=>{const t=performance.now();if(!end&&t-predT<140)return;predT=t;predict();};\n if(!trainable()){$('#tGuess').innerHTML='<small>צריך לפחות 2 מילים במוח</small>';}\n}\n/* ---- זיהוי משולב: הרשת + \"הציור הכי דומה ששמרת\" (משותף לאפליקציה ולשרת, מוזרק בבנייה) ---- */\nconst KNN_ANG = [-45, -30, -15, 15, 30, 45];\n// הכנה: שחור־לבן, עובי קו אחיד, טשטוש, ונרמול (וקטור יחידה ממורכז) – כך שמכפלה = מתאם צורה\nfunction knnPrep(d, S) {\n  const n = S * S, f = 28 / S, b = new Uint8Array(n), t = new Uint8Array(n), o = new Float32Array(n), h = new Float32Array(n);\n  for (let y = 0; y < 28; y++) for (let x = 0; x < 28; x++) if (d[y * 28 + x] >= 6) b[((y / f) | 0) * S + ((x / f) | 0)] = 1;\n  if (S === 28) {\n    for (let y = 0, i = 0; y < S; y++) for (let x = 0; x < S; x++, i++) t[i] = b[i] | (x > 0 ? b[i - 1] : 0) | (x < S - 1 ? b[i + 1] : 0);\n    for (let y = 0, i = 0; y < S; y++) for (let x = 0; x < S; x++, i++) o[i] = t[i] | (y > 0 ? t[i - S] : 0) | (y < S - 1 ? t[i + S] : 0);\n  } else for (let i = 0; i < n; i++) o[i] = b[i];\n  for (let pass = 0; pass < (S === 28 ? 2 : 1); pass++) {\n    for (let y = 0, i = 0; y < S; y++) for (let x = 0; x < S; x++, i++) { let s = o[i], c = 1; if (x > 0) { s += o[i - 1]; c++; } if (x < S - 1) { s += o[i + 1]; c++; } h[i] = s / c; }\n    for (let y = 0, i = 0; y < S; y++) for (let x = 0; x < S; x++, i++) { let s = h[i], c = 1; if (y > 0) { s += h[i - S]; c++; } if (y < S - 1) { s += h[i + S]; c++; } o[i] = s / c; }\n  }\n  let m = 0; for (let i = 0; i < n; i++) m += o[i]; m /= n;\n  let q = 0; for (let i = 0; i < n; i++) { o[i] -= m; q += o[i] * o[i]; }\n  q = 1 / (Math.sqrt(q) + 1e-9); for (let i = 0; i < n; i++) o[i] *= q;\n  return o;\n}\nfunction knnDot(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }\n// דמיון לכל מילה = הדמיון לציור הכי דומה שלה. exs: [{c, d}] ; must: מילים שחייבים לחשב במדויק\nfunction wordSims(d, exs, K, must) {\n  const s1 = new Float32Array(K), q14 = knnPrep(d, 14);\n  for (const e of exs) { const u = e.u14 || (e.u14 = knnPrep(e.d, 14)); const v = knnDot(q14, u); if (v > s1[e.c]) s1[e.c] = v; }\n  const cand = new Set(must || []);\n  [...s1].map((v, i) => [v, i]).sort((a, b) => b[0] - a[0]).slice(0, 6).forEach(x => cand.add(x[1]));\n  const qs = [knnPrep(d, 28)].concat(KNN_ANG.map(a => knnPrep(tf8(d, a), 28)));\n  const s = new Float32Array(K);\n  for (const e of exs) {\n    if (!cand.has(e.c)) continue;\n    const u = e.u28 || (e.u28 = knnPrep(e.d, 28));\n    for (const q of qs) { const v = knnDot(q, u); if (v > s[e.c]) s[e.c] = v; }\n  }\n  return s;\n}\n// שילוב: חצי מהרשת, חצי מהציור הכי דומה\nfunction mixP(p, s) {\n  const K = p.length, q = new Float32Array(K); let mx = 0, sum = 0;\n  for (let i = 0; i < K; i++) if (s[i] > mx) mx = s[i];\n  for (let i = 0; i < K; i++) { q[i] = s[i] > 0 ? Math.exp((s[i] - mx) / 0.04) : 0; sum += q[i]; }\n  const P = new Float32Array(K);\n  for (let i = 0; i < K; i++) P[i] = 0.5 * p[i] + 0.5 * (sum ? q[i] / sum : 1 / K);\n  return P;\n}\n// המילה שנבחרת = זו עם ציון ההתאמה הכי גבוה (ביטחון × דמיון); אם הכל 0 – לפי הביטחון בלבד\nfunction bestWord(P, s, lo, hi) {\n  let b = -1, bv = 0, a = 0;\n  for (let i = 0; i < P.length; i++) { const v = P[i] * Math.min(1, Math.max(0, (s[i] - lo) / (hi - lo))); if (v > bv) { bv = v; b = i; } if (P[i] > P[a]) a = i; }\n  return b >= 0 ? b : a;\n}\n\nlet lastTestD=null;\nfunction predict(){\n const d=grabPad();lastTestD=d;const g=$('#tGuess'),bars=$('#tBars');\n if(!d||!trainable()){g.innerHTML='';bars.innerHTML='';return;}\n const p0=forward(toX(d)).p,topP=[...p0].map((v,i)=>[v,i]).sort((a,b)=>b[0]-a[0]).slice(0,6).map(x=>x[1]);\n // זיהוי משולב: הרשת + הציור הכי דומה ששמרת\n const sv=wordSims(d,S.ex,S.cats.length,topP),p=mixP(p0,sv),k=bestWord(p,sv,SIM_LO,SIM_HI),sim=sv[k],pass=sim>=SIM_OK,conf=p[k]*simFactor(sim);\n g.innerHTML=`<small>${pass?'זה':'אולי…'}</small><span></span><small class=\"num\">${Math.round(conf*100)}%</small><em class=\"simTag ${pass?'ok':'no'}\">דמיון ${Math.round(sim*100)}% · ${pass?'יזוהה באתגר':'לא יזוהה באתגר'}</em>`;g.querySelector('span').textContent=S.cats[k].w;g.className='guess lv'+LVL.get(S.cats[k].w);g.querySelector('span').style.color='var(--lc)';\n bars.innerHTML='';\n // העמודות: 3 המילים שהמוח הכי חושב שמתאימות; האחוז = הציון שקובע זיהוי באתגר (ביטחון × דמיון)\n [...p].map((v,i)=>[v*simFactor(sv[i]),i]).sort((a,b)=>b[0]-a[0]).slice(0,3).forEach(([v,i])=>{\n  const w=S.cats[i].w,b=document.createElement('button');b.className='bar lv'+LVL.get(w);\n  b.innerHTML=`<span class=\"nm\"></span><span class=\"tr\"><span class=\"fl\" style=\"display:block;width:${(v*100).toFixed(1)}%\"></span></span><span class=\"pc num\">${Math.round(v*100)}%</span>`;\n  b.querySelector('.nm').textContent=w;b.onclick=()=>teachFromTest(i);bars.appendChild(b);});\n}\n$('#tOther').onclick=()=>{\n if(!lastTestD){toast('ציירו קודם, ואז בחרו את המילה');return;}\n $('#pickQ').value='';renderPick();openSheet('#shPick');\n};\n$('#pickQ').addEventListener('input',renderPick);\nfunction renderPick(){\n const q=$('#pickQ').value.trim(),c=counts(),box=$('#pickGrid');box.innerHTML='';\n let items;\n if(q)items=[1,2,3].flatMap(l=>WORDS[l].filter(w=>w.includes(q)).map(w=>[w,l])).concat(S.cats.filter(x=>!LVL.has(x.w)&&x.w.includes(q)).map(x=>[x.w,4]));\n else items=S.cats.map(x=>[x.w,LVL.get(x.w)]).sort((a,b)=>a[0].localeCompare(b[0],'he'));\n if(!q&&items.length){const h=document.createElement('div');h.className='letterHd';h.textContent='המילים שבמוח · או חפשו מילה חדשה';box.appendChild(h);}\n if(!items.length){box.innerHTML='<div class=\"empty\"><b>המילה לא במאגר</b><span>אפשר לבחור רק מתוך 300 המילים של המשחק</span></div>';return;}\n const frag=document.createDocumentFragment();\n items.forEach(([w,l])=>{const k=catIndex(w),n=k>=0?c[k]:0,b=document.createElement('button');b.className='wr lv'+l+(k>=0?' in':'');b.disabled=n>=MAX_EX;\n  b.innerHTML=`<b></b>${k>=0?`<span class=\"st\">${meter(n,l)}<span class=\"num\">${n}/${MAX_EX}</span></span>`:`<span class=\"tag\">${LVNAME[l]} · חדשה</span>`}`;\n  b.querySelector('b').textContent=w;\n  b.onclick=()=>{closeSheets();const kk=ensureCat(w);teachFromTest(kk);if(cur.view==='vRoom')renderRoom();};\n  frag.appendChild(b);});\n box.appendChild(frag);\n}\nfunction teachFromTest(k){\n if(!lastTestD)return;if(byCat()[k].length>=MAX_EX){toast(`\"${S.cats[k].w}\" כבר מלאה (10/10)`);return;}\n S.ex.push({c:k,d:lastTestD,L:lastL});learnFx(lastTestD,S.cats[k].w);dirty();kickTrain();clearPad();$('#tGuess').innerHTML='';$('#tBars').innerHTML='';lastTestD=null;\n}\n\n/* ---------- כיכר ---------- */\nlet sqCache=[];\nasync function renderSquare(){\n $$('#sqSeg button').forEach(b=>b.classList.toggle('on',b.dataset.s===cur.sq));\n renderSquareList();\n try{if(cur.sq==='open')sqCache=(await api('square')).challenges;else await loadMine();}catch(e){toast(e.message);}\n renderSquareList();\n}\n$$('#sqSeg button').forEach(b=>b.onclick=()=>{cur.sq=b.dataset.s;renderSquare();});\nfunction emptyHTML(t,s){return `<div class=\"empty\"><svg viewBox=\"0 0 64 64\"><use href=\"#mascotBig\"/></svg><b>${t}</b><span>${s}</span></div>`;}\nfunction ago(t){const m=Math.round((Date.now()-t)/60000);return m<1?'עכשיו':m<60?`לפני ${m} דק׳`:m<1440?`לפני ${Math.round(m/60)} שע׳`:`לפני ${Math.round(m/1440)} ימים`;}\nfunction renderSquareList(){\n const box=$('#sqList');box.innerHTML='';\n if(cur.sq==='open'){\n  if(!sqCache.length){box.innerHTML=emptyHTML('אין אתגרים פתוחים','כשמישהו יפרסם מילה מהמוח שלו – היא תופיע כאן');return;}\n  sqCache.forEach(c=>{const b=document.createElement('button');b.className='chRow lv'+c.lvl;\n   b.innerHTML=`<div class=\"grow\"><div class=\"chWord\"></div><div class=\"chMeta\"><span class=\"o\"></span> · ${c.k} מילים · ${c.n} ${c.n===1?'ציור':'ציורים'}</div>${MODE!=='ink'&&c.curse&&CURSE[c.curse]?`<div class=\"cTag\">${CURSE[c.curse].t}${c.cmult>1?` · <bdi>×${c.cmult}</bdi>`:''}</div>`:''}</div><div class=\"chPts num\">${MODE==='ink'?`<bdi>${c.min}–${c.max}</bdi><small>נקודות</small>`:`${c.max}<small>עד</small>`}</div>`;\n   b.querySelector('.chWord').textContent=c.word;b.querySelector('.o').textContent='המוח של '+c.owner;if(c.my)b.querySelector('.chMeta').insertAdjacentHTML('beforeend',` · <span style=\"color:var(--bad)\">ניסית ${c.my===1?'פעם אחת':c.my+' פעמים'}</span>`);if(c.bot)b.querySelector('.o').insertAdjacentHTML('afterend','<em class=\"botTag\"><svg class=\"ic\"><use href=\"#i-bot\"/></svg>מחשב</em>');b.onclick=()=>{cur.ch=c;go('vDraw');};box.appendChild(b);});\n }else{\n  if(!mineCache.length){box.innerHTML=emptyHTML('עוד לא פרסמת אתגרים','במוח שלי ← 5 מילים לפחות ← בוחרים מילה ← פרסם אתגר');return;}\n  mineCache.forEach(c=>{const r=document.createElement('div');r.className='chRow lv'+c.lvl;\n   r.innerHTML=`<div class=\"grow\"><div class=\"chWord\"></div><div class=\"chMeta\"></div></div>`;\n   r.querySelector('.chWord').textContent=c.word;\n   const m=r.querySelector('.chMeta');\n   if(c.status==='open'){m.innerHTML=`<span class=\"chSt open\">פתוח</span> · ${c.tries} ניסיונות${c.solves?` · <span class=\"chSt solved\">${c.solves===1?'פתר אחד':`פתרו ${c.solves}`}</span>`:''} · ${ago(c.created)}`;const x=document.createElement('button');x.className='xBtn';x.setAttribute('aria-label','הסרת האתגר');x.innerHTML='<svg class=\"ic\"><use href=\"#i-x\"/></svg>';x.onclick=async()=>{if(!await ask(`להסיר את \"${c.word}\" מהכיכר?`,'שחקנים כבר לא יוכלו לנסות אותה.','הסרה'))return;try{await api('challenge/'+c.id,{method:'DELETE'});await loadMine();}catch(e){toast(e.message);}};r.appendChild(x);}\n   else{m.innerHTML=`<span class=\"chSt solved\">נפתר</span> · <span class=\"s\"></span> · ${c.tries} ניסיונות`;m.querySelector('.s').textContent='ע״י '+(c.solver||'');}\n   if(c.tries>0){const v=document.createElement('button');v.className='recBtn';v.innerHTML='<svg class=\"ic\"><use href=\"#i-pen\"/></svg>צפה בציורים';v.onclick=()=>openRecs(c);r.querySelector('.grow').appendChild(v);}\n   box.appendChild(r);});\n }\n}\n\n/* ---------- ציור אתגר ---------- */\nfunction renderDraw(){\n const c=cur.ch;$('#vDraw').className='view on lv'+c.lvl;$('#dRes').classList.add('hide');REC=[];recT0=0;\n $('#dWord').textContent=c.word;$('#dPts').className='chPts'+(MODE==='ink'?' live':'');liveShown=-1;if(MODE==='ink')paintLive();else $('#dPts').innerHTML=`${c.max}<small>עד</small>`;\n $('#dSub').textContent=`המוח של ${c.owner} ישפוט · ${c.k} מילים · ${c.n} ${c.n===1?'ציור':'ציורים'} · מכפיל ${c.mult} · ${c.my?`ניסיון ${c.my+1}`:'אפשר לנסות שוב'}`;paintCurse();loadTries(c);\n $('#dSend').disabled=false;$('#dSend').innerHTML='<svg class=\"ic\"><use href=\"#i-send\"/></svg>'+SEND_LABEL;\n}\n$('#dSend').onclick=async()=>{\n const c=cur.ch,d=grabPad();\n if(!d&&!await ask('הלוח ריק','לשלוח בכל זאת? זה ייחשב ככישלון.','שליחה'))return;\n const b=$('#dSend');b.disabled=true;b.textContent='המוח חושב…';padLocked=true;clearInterval(curseTimer);\n try{const r=await api('attempt',{method:'POST',body:{id:c.id,d:d?dToStr(d):'',L:lastL,rec:REC.length?recB64():''}});showResult(r,d);refreshMe();}\n catch(e){toast(e.message);padLocked=false;b.disabled=false;b.innerHTML='<svg class=\"ic\"><use href=\"#i-send\"/></svg>'+SEND_LABEL;}\n};\nfunction showResult(r,d){\n const box=$('#dRes'),pc=Math.round(r.conf*100);box.className='result '+(r.ok?'win':'lose');\n box.innerHTML=`<div class=\"badge\"><svg class=\"ic\"><use href=\"#i-${r.ok?'check':'x'}\"/></svg></div><h2>${r.ok?'המוח זיהה!':'המוח לא זיהה'}</h2><p></p><canvas class=\"mini\"></canvas><div class=\"pts num\"><bdi>${r.points<0?'−'+(-r.points):r.points}</bdi><small>נקודות</small></div><div class=\"formula\"></div>${r.ok?'':'<button class=\"btn pri\" id=\"resAgain\" style=\"margin-bottom:8px\">נסה שוב</button>'}<button class=\"btn dark\" id=\"resBack\">חזרה לכיכר</button>`;\n const sp=Math.round((r.sim||0)*100);\n box.querySelector('p').textContent=r.empty?'לא צויר כלום':r.ok?`המוח של ${r.owner} זיהה \"${r.word}\" · דמיון ${sp}% לציורים שלו`:r.guess?`המוח של ${r.owner} חשב שזה \"${r.guess}\"`:`המוח ניחש \"${r.word}\", אבל הציור דומה רק ${sp}% לציורים של ${r.owner} (צריך 80%)`;\n box.querySelector('.formula').textContent=r.ok?`${pc}% × ${r.mult} (${r.n} ${r.n===1?'ציור':'ציורים'})${r.imult>1?` × ${r.imult} (דיו ${Math.round((r.inkR||1)*100)}%)`:''}${r.cmult>1?` × ${r.cmult} (מראה)`:''} × ${(1+sizeBonus(r.k)).toFixed(2)} (${r.k} מילים) × ${BASE[r.lvl]} · אותו ניקוד גם ל${r.owner}`:`איבדת ${-r.points} נקודות (מכפיל ${Math.round(r.mult*(r.cmult||1)*10)/10}) · ${r.owner} לא מפסיד · אפשר לנסות שוב`;\n const mini=box.querySelector('.mini');if(d)thumb(d,mini);else mini.remove();\n box.querySelector('#resBack').onclick=()=>{cur.stack=[];go('vSquare',false);};\n const ag=box.querySelector('#resAgain');if(ag)ag.onclick=()=>{cur.ch.my=(cur.ch.my||0)+1;padLocked=false;clearPad();renderDraw();};\n}\n\n/* ---------- הניסיונות הקודמים שלי באתגר ---------- */\nasync function loadTries(c){\n const box=$('#dTries');box.classList.add('hide');box.innerHTML='';if(!c.my)return;\n try{const {attempts}=await api('mytries?c='+encodeURIComponent(c.id));if(cur.ch!==c||!attempts.length)return;\n  box.innerHTML='<small>הניסיונות שלך:</small>';\n  attempts.forEach(a=>{const b=document.createElement('button');b.className='tryC';const cv=document.createElement('canvas');\n   if(a.d){const d=new Uint8Array(IN);for(let i=0;i<IN;i++)d[i]=parseInt(a.d[i],16);thumb(d,cv);}\n   b.append(cv);const t=document.createElement('span');t.className='num';t.textContent=Math.round((a.conf||0)*100)+'%';b.append(t);\n   b.onclick=()=>playRec(a.id);box.appendChild(b);});\n  box.classList.remove('hide');\n }catch(e){}\n}\n\n/* ---------- צפייה בציור של מי שניסה את האתגר ---------- */\nlet recRAF=0,recCur=null;\nasync function openRecs(c){\n $('#recsT').textContent=`מי צייר את \"${c.word}\"`;const box=$('#recsList');box.innerHTML='<div class=\"nr\">טוען…</div>';openSheet('#shRecs');\n try{const {attempts}=await api('recs?c='+encodeURIComponent(c.id));box.innerHTML='';\n  if(!attempts.length){box.innerHTML='<div class=\"nr\">עוד אין ניסיונות</div>';return;}\n  if(attempts.length===1){playRec(attempts[0].id);return;}\n  attempts.forEach(a=>{const b=document.createElement('button');b.className='recRow '+(a.ok?'win':'lose');b.innerHTML=`<svg class=\"ic\"><use href=\"#i-pen\"/></svg><b></b><span class=\"num\">${sgn(a.points)}</span>`;b.querySelector('b').textContent=(a.bot?'🤖 ':'')+a.drawer+' · '+ago(a.created);b.onclick=()=>playRec(a.id);box.appendChild(b);});\n }catch(e){box.innerHTML='';toast(e.message);}\n}\nasync function playRec(id){\n closeSheets();openSheet('#shRec');$('#recT').textContent='טוען…';const res=$('#recRes');res.className='recRes';res.innerHTML='';\n const cv=$('#recC'),x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,280,280);cancelAnimationFrame(recRAF);\n try{const {attempt:a}=await api('rec/'+id);recCur=a;runRec();}catch(e){$('#recT').textContent='';toast(e.message);}\n}\nfunction runRec(){\n const a=recCur;if(!a)return;cancelAnimationFrame(recRAF);\n $('#recT').textContent=a.mine?`הציור שלך: \"${a.word}\"…`:`${a.bot?'🤖 ':''}${a.drawer} מצייר \"${a.word}\"…`;\n const res=$('#recRes');res.className='recRes';res.innerHTML='';\n const cv=$('#recC'),x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,280,280);x.lineCap='round';x.lineJoin='round';\n const done=()=>{$('#recT').textContent=a.mine?`הציור שלך: \"${a.word}\"`:`${a.bot?'🤖 ':''}${a.drawer} צייר \"${a.word}\"`;\n  const pc=Math.round((a.conf||0)*100),pts=a.ok?a.points:(a.bot?0:a.points);\n  res.className='recRes '+(a.ok?'win':'lose');\n  const ptsMine=a.mine?a.points:pts,brain=a.mine?`המוח של ${a.owner}`:'המוח שלך';\n  res.innerHTML=`<b></b><span></span> · <span class=\"num\">${sgn(ptsMine)}</span> נקודות`;\n  res.querySelector('b').textContent=a.ok?`${brain} זיהה! ✓`:`${brain} לא זיהה ✗`;\n  res.querySelector('span').textContent=`המוח הבין ${pc}%`+(a.ok?'':a.guess?` · חשב שזה \"${a.guess}\"`:` · לא דומה מספיק לציורים של${a.mine?' '+a.owner:'ך'}`);\n  requestAnimationFrame(()=>res.classList.add('on'));};\n if(a.rec){\n  const s=atob(a.rec),ev=[];for(let i=0;i+3<s.length;i+=4)ev.push([s.charCodeAt(i),s.charCodeAt(i+1)/255*280,s.charCodeAt(i+2)/255*280,Math.min(60,s.charCodeAt(i+3)*10)]);\n  let i=0,t=0,clock=performance.now(),last=null,er=false;\n  const step=now=>{t+=Math.min(100,now-clock)*1.4;clock=now;\n   while(i<ev.length&&t>=ev[i][3]){const [k,px,py,dt]=ev[i];t-=dt;\n    if(k===3){x.fillStyle='#fff';x.fillRect(0,0,280,280);last=null;}\n    else{const p={x:px,y:py};if(k<2){er=k===1;last=p;}\n     x.strokeStyle=er?'#fff':'#1F2440';x.lineWidth=er?40:18;x.beginPath();x.moveTo(last.x,last.y);x.lineTo(p.x+.01,p.y);x.stroke();last=p;}\n    i++;}\n   if(i<ev.length)recRAF=requestAnimationFrame(step);else setTimeout(done,350);};\n  recRAF=requestAnimationFrame(step);\n }else if(a.d){\n  // אין הקלטה (למשל מחשב) – הציור מתגלה בהדרגה\n  const v=[...a.d].map(h=>parseInt(h,16)),px=[];v.forEach((q,j)=>{if(q)px.push(j);});px.sort((p,q)=>(p%28+(p/28|0))-(q%28+(q/28|0)));\n  const part=new Uint8Array(IN);let j=0;\n  const step=()=>{for(let n=0;n<8&&j<px.length;n++,j++)part[px[j]]=v[px[j]];bigDraw(cv,part);\n   if(j<px.length)recRAF=requestAnimationFrame(step);else setTimeout(done,350);};recRAF=requestAnimationFrame(step);\n }else done();\n}\n$('#recAgain').onclick=runRec;\n$('#recClose').onclick=()=>{cancelAnimationFrame(recRAF);closeSheets();};\n\n/* ---------- דירוג ---------- */\nasync function renderLeaders(){\n try{const {leaders}=await api('leaders');const box=$('#lbList');box.innerHTML='';\n  leaders.forEach((p,i)=>{const r=document.createElement('div');r.className='lr'+(AUTH&&p.id===AUTH.id?' me':'');\n   r.innerHTML=`<span class=\"rk num\">${i+1}</span><div class=\"nm\"><span></span>${p.bot?'<em class=\"botTag\"><svg class=\"ic\"><use href=\"#i-bot\"/></svg>מחשב</em>':''}<small>מוח של ${p.words} מילים</small></div><span class=\"sc num\">${p.score}</span>`;r.querySelector('.nm span').textContent=p.name;box.appendChild(r);});\n  if(!leaders.length)box.innerHTML=emptyHTML('עוד אין שחקנים','');\n }catch(e){toast(e.message);}\n refreshMe();\n}\n\n/* ---------- אני, התראות ---------- */\nlet ME=null,shownNotes=new Set();\nasync function refreshMe(){\n if(!AUTH)return;\n try{const r=await api('me');ME=r.me;\n  $('#hScore span').textContent=ME.score;$('#hMe').textContent=ME.name.trim()[0]||'?';\n  $('#lbRank').textContent=ME.rank;$('#lbName').textContent=ME.name;$('#lbScore').textContent=`${ME.score} נקודות`;\n  $('#bellDot').classList.toggle('hide',!r.notes.length);\n  const fresh=r.notes.filter(n=>!shownNotes.has(n.id));fresh.forEach(n=>shownNotes.add(n.id));\n  const ext=fresh.filter(n=>n.kind==='win'||n.kind==='lose');\n  if(ext.length){toast(ext[ext.length-1].text);loadMine();}\n }catch(e){}\n}\nfunction openSheet(id){$('#scrim').classList.add('on');$(id).classList.add('on');}\nfunction closeSheets(){$('#scrim').classList.remove('on');$$('.sheet').forEach(s=>s.classList.remove('on'));}\n$('#scrim').onclick=()=>{if(askR)askDone(false);else closeSheets();};\n$('#hScore').onclick=()=>{cur.stack=[];go('vLeaders',false);};\n$('#hBell').onclick=async()=>{\n openSheet('#shNotes');const box=$('#noteList');box.innerHTML='<div class=\"nr\">טוען…</div>';\n try{const {notes}=await api('notes');box.innerHTML='';\n  if(!notes.length)box.innerHTML='<div class=\"nr\">אין עדיין התראות. פרסמו אתגר או נסו אתגר מהכיכר.</div>';\n  notes.forEach(n=>{const r=document.createElement('div');r.className='nr '+(n.points>0?'win':'lose')+(n.seen?'':' new');r.innerHTML=`<b class=\"num\">${sgn(n.points)}</b><div><span></span><time>${ago(n.created)}</time></div>`;r.querySelector('span').textContent=n.text;\n   if(n.aid){const v=document.createElement('button');v.className='recBtn';v.innerHTML='<svg class=\"ic\"><use href=\"#i-pen\"/></svg>צפה בציור';v.onclick=()=>playRec(n.aid);r.querySelector('div').appendChild(v);}\n   box.appendChild(r);});\n  await api('notes/seen',{method:'POST'});$('#bellDot').classList.add('hide');\n }catch(e){box.innerHTML='';toast(e.message);}\n};\nconst isIOS=/iPhone|iPad|iPod/.test(navigator.userAgent),standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;\n$('#hMe').onclick=()=>{\n if(!ME)return;$('#meName').textContent=ME.name;$('#meCode').textContent=ME.code;\n const canPush='serviceWorker' in navigator&&'PushManager' in window&&!SIM&&!DEMO;\n $('#iosSteps').classList.toggle('hide',!(isIOS&&!standalone));$('#purgeBtn').classList.toggle('hide',!(String(ME.code)==='6351'&&ME.name.startsWith('ארנ'))||NS!=='live');\n const pb=$('#pushBtn');pb.classList.toggle('hide',!canPush);\n pb.disabled=typeof Notification!=='undefined'&&Notification.permission==='granted';pb.innerHTML=pb.disabled?'<svg class=\"ic\"><use href=\"#i-check\"/></svg>התראות פעילות':'<svg class=\"ic\"><use href=\"#i-bell\"/></svg>הפעלת התראות';\n openSheet('#shMe');\n};\n$('#pushBtn').onclick=()=>enablePush(true);\n// ניהול: מחיקת כל השחקנים חוץ ממנהל המשחק והרובוטים\n$('#purgeBtn').onclick=async()=>{\n try{const {names}=await api('admin/purge');\n  if(!names.length){toast('אין שחקנים למחיקה');return;}\n  if(!await ask(`למחוק ${names.length} שחקנים?`,names.join(' · ')+' – כולל המוחות, האתגרים וההתראות שלהם. אי אפשר לשחזר.','מחיקה'))return;\n  const r=await api('admin/purge',{method:'POST'});toast(`נמחקו ${r.deleted} שחקנים`);closeSheets();\n }catch(e){toast(e.message);}\n};\n$('#logout').onclick=async()=>{closeSheets();if(await ask('להתנתק?','אפשר לחזור עם השם והקוד.','התנתקות'))logout(false);};\nfunction logout(expired){AUTH=null;ls.del('auth');ls.del('brain');S={cats:[],ex:[],rounds:0,updated:0};newNet();closeSheets();showLogin();if(expired)toast('צריך להתחבר מחדש');}\nfunction b64u2u(s){s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u;}\nasync function enablePush(fromBtn){\n try{\n  if(SIM||!('serviceWorker' in navigator)||!('PushManager' in window)){if(fromBtn)toast(isIOS?'באייפון: הוסיפו קודם למסך הבית':'הדפדפן לא תומך בהתראות');return;}\n  const {key}=await api('vapid');if(!key){if(fromBtn)toast('התראות עוד לא הוגדרו בשרת');return;}\n  const perm=await Notification.requestPermission();if(perm!=='granted'){if(fromBtn)toast('ההתראות לא אושרו');return;}\n  const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();\n  if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64u2u(key)});\n  await api('push/sub',{method:'POST',body:{endpoint:sub.endpoint}});\n  if(fromBtn){toast('התראות פעילות');closeSheets();}\n }catch(e){if(fromBtn)toast('לא הצלחנו להפעיל התראות');}\n}\nfunction maybeAskPush(){if(SIM||DEMO||typeof Notification==='undefined'||Notification.permission!=='default'||ls.get('askedPush',false))return;ls.set('askedPush',true);setTimeout(async()=>{if(await ask('לקבל התראות?','נודיע כשמישהו מנסה את האתגר שלך.','הפעלה'))enablePush(true);},600);}\n\n/* ---------- כניסה ---------- */\nlet loginMode='new',newAcc=null;\n$$('#loginSeg button').forEach(b=>b.onclick=()=>{loginMode=b.dataset.m;$$('#loginSeg button').forEach(x=>x.classList.toggle('on',x===b));$('#lNew').classList.toggle('hide',loginMode!=='new');$('#lOld').classList.toggle('hide',loginMode!=='old');$('#lGo').textContent=loginMode==='new'?'יוצרים שחקן':'כניסה';$('#lErr').textContent='';});\nfunction showLogin(){go('vLogin',false);newAcc=null;$('#lCode').classList.add('hide');$('#loginSeg').classList.remove('hide');$('#lNew').classList.toggle('hide',loginMode!=='new');$('#lOld').classList.toggle('hide',loginMode!=='old');$('#lGo').textContent=loginMode==='new'?'יוצרים שחקן':'כניסה';if(SIM&&!$('#inName').value)$('#inName').value='שחקן '+SLOT;}\n$('#lGo').onclick=async()=>{\n const b=$('#lGo'),e=$('#lErr');e.textContent='';\n if(newAcc){await enter(newAcc);return;}\n b.disabled=true;\n try{\n  if(loginMode==='new'){const r=await api('register',{method:'POST',body:{name:$('#inName').value}});newAcc=r;$('#codeShow').textContent=r.code;$('#lCode').classList.remove('hide');$('#lNew').classList.add('hide');$('#loginSeg').classList.add('hide');b.textContent='שמרתי – יאללה לצייר';}\n  else{const r=await api('login',{method:'POST',body:{name:$('#inName2').value,code:$('#inCode').value}});await enter(r);}\n }catch(x){e.textContent=x.message;}\n b.disabled=false;\n};\n['#inName','#inName2','#inCode'].forEach(s=>$(s).addEventListener('keydown',e=>{if(e.key==='Enter')$('#lGo').click();}));\nasync function enter(r){AUTH={id:r.id,token:r.token,name:r.name};ls.set('auth',AUTH);$('#lGo').textContent='טוען את המוח…';await boot();}\n\n/* ---------- התחלה ---------- */\nasync function boot(){\n await loadBrain();cur.stack=[];go('vRoom',false);refreshMe();loadMine();\n if(trainable()&&(S.rounds===0||!ls.get('aug8',false))){ls.set('aug8',true);kickTrain();}\n}\n\nif('serviceWorker' in navigator&&!SIM&&!DEMO)navigator.serviceWorker.register('/sw.js').catch(()=>{});\nnewNet();\nif(SOLO)document.body.classList.add('solo');\nif(AUTH)boot();else if(SOLO)api('register',{method:'POST',body:{name:'שחקן '+Math.floor(Math.random()*9000+1000)}}).then(enter).catch(()=>showLogin());else showLogin();\nsetInterval(()=>{if(AUTH&&!document.hidden)refreshMe();},SIM?6000:15000);\ndocument.addEventListener('visibilitychange',()=>{if(!document.hidden&&AUTH){refreshMe();if(cur.view==='vSquare')renderSquare();}else if(document.hidden&&pendingUp)upload();});\n</script>\n</body>\n</html>\n";
const SIM = "<!doctype html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex\">\n<title>צייר המוחות – הדמיית 8 טלפונים</title>\n<link rel=\"icon\" href=\"/icon.svg\" type=\"image/svg+xml\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--paper:#FBF6EC;--paper2:#F2E9D8;--sheet:#FFFDF8;--ink:#1F2440;--ink2:#565A78;--ink3:#8A8DA6;--line:#E3D7C0;--accent:#E2461F;\n --l1:#1A8E58;--l1bg:#DCF2E5;--l2:#B87400;--l2bg:#FBEBC8;--l3:#6343D6;--l3bg:#E8E2FB;--ok:#1A8E58;--bad:#CF3338;font-family:\"Fredoka\",system-ui,sans-serif}\n*{box-sizing:border-box;margin:0}\nhtml,body{height:100%;background:#2A2F4F;color:var(--ink);overflow:hidden}\nbutton{font:inherit;border:0;cursor:pointer}\n.num{font-variant-numeric:tabular-nums}\n#wrap{display:grid;grid-template-columns:1fr 330px;grid-template-rows:56px 1fr;height:100%}\nheader{grid-column:1/-1;display:flex;align-items:center;gap:12px;padding:0 18px;background:#1F2440;color:#fff}\nheader h1{font-size:20px;font-weight:700;flex:1}\nheader h1 span{font-weight:400;opacity:.7;font-size:15px;margin-right:8px}\n.hb{height:38px;padding:0 16px;border-radius:12px;background:#3A4068;color:#fff;font-weight:600;font-size:15px}\n.hb.red{background:var(--accent)}\n#phones{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:max-content;gap:18px 14px;padding:14px;min-height:0;overflow-y:auto;align-content:start;scrollbar-color:#4A5080 transparent}\n.ph{position:relative;display:flex;flex-direction:column;align-items:center;min-height:0}\n.ph .lab{position:absolute;top:0;right:4px;color:#C9CCE4;font-size:13px;font-weight:600;display:flex;gap:6px;align-items:center;z-index:2}\n.ph .lab button{background:#3A4068;color:#fff;border-radius:8px;height:22px;padding:0 8px;font-size:12px}\n.hold{position:relative;flex:none;margin-top:14px}\n.frame{position:absolute;top:0;left:0;width:390px;height:800px;border-radius:44px;background:#0E1124;padding:10px;box-shadow:0 18px 40px -18px #000;transform-origin:0 0}\n.frame iframe{width:370px;height:780px;border:0;border-radius:34px;background:var(--paper);display:block}\naside{background:var(--paper);overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:16px;border-right:1px solid #11152c}\naside h2{font-size:17px;font-weight:700;margin-bottom:6px}\n.stats{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px}\n.st{background:var(--sheet);border:1.5px solid var(--line);border-radius:12px;padding:8px;text-align:center}\n.st b{display:block;font-size:22px}\n.st span{font-size:12.5px;color:var(--ink2)}\n.lv1{--lc:var(--l1);--lb:var(--l1bg)}.lv2{--lc:var(--l2);--lb:var(--l2bg)}.lv3{--lc:var(--l3);--lb:var(--l3bg)}\n.lvRow{display:flex;align-items:center;gap:8px;font-size:14px;padding:6px 0}\n.lvRow .nm{width:62px;font-weight:600;color:var(--lc)}\n.lvRow .tr{flex:1;height:12px;border-radius:6px;background:var(--paper2);overflow:hidden}\n.lvRow .fl{height:100%;background:var(--lc)}\n.lvRow .v{width:96px;text-align:left;color:var(--ink2);font-size:12.5px}\n.box{background:var(--sheet);border:1.5px solid var(--line);border-radius:14px;overflow:hidden}\n.lr{display:flex;gap:8px;align-items:center;padding:7px 12px;border-bottom:1px solid var(--paper2);font-size:14.5px}\n.lr:last-child{border-bottom:0}\n.lr i{font-style:normal;width:20px;color:var(--ink3);font-weight:600}\n.lr span{flex:1}\n.lr small{color:var(--ink3)}\n.fr{padding:8px 12px;border-bottom:1px solid var(--paper2);font-size:13.5px;line-height:1.4}\n.fr:last-child{border-bottom:0}\n.fr b.w{color:var(--lc)}\n.fr .p{float:left;font-weight:700}\n.fr.ok .p{color:var(--ok)}.fr.no .p{color:var(--bad)}\n.empty{padding:14px;color:var(--ink2);font-size:14px;text-align:center}\n</style>\n</head>\n<body>\n<div id=\"wrap\">\n <header>\n  <h1>צייר המוחות<span>הדמיה · 8 טלפונים · סביבת בדיקה נפרדת</span></h1>\n  <label class=\"hb\" style=\"display:flex;align-items:center;gap:6px;cursor:pointer\"><input type=\"checkbox\" id=\"fit\">כל 8 במסך אחד</label>\n  <button class=\"hb\" id=\"reload\">רענון כל הטלפונים</button>\n  <button class=\"hb red\" id=\"reset\">איפוס סביבת הבדיקה</button>\n </header>\n <section id=\"phones\"></section>\n <aside>\n  <div><h2>מצב המשחק</h2>\n   <div class=\"stats\"><div class=\"st\"><b class=\"num\" id=\"sOpen\">0</b><span>אתגרים פתוחים</span></div><div class=\"st\"><b class=\"num\" id=\"sTries\">0</b><span>ניסיונות</span></div><div class=\"st\"><b class=\"num\" id=\"sRate\">–</b><span>הצלחה</span></div></div>\n  </div>\n  <div><h2>הצלחה לפי רמה</h2><div id=\"lv\"></div></div>\n  <div><h2>דירוג</h2><div class=\"box\" id=\"lb\"></div></div>\n  <div><h2>מה קרה עכשיו</h2><div class=\"box\" id=\"feed\"></div></div>\n </aside>\n</div>\n<script>\nconst $=s=>document.querySelector(s);\nconst LV={1:'פשוטות',2:'בינוניות',3:'מורכבות'};\nconst ph=$('#phones');\nfor(let i=1;i<=8;i++){\n const d=document.createElement('div');d.className='ph';\n d.innerHTML=`<div class=\"lab\">טלפון ${i}<button>רענון</button></div><div class=\"hold\"><div class=\"frame\"><iframe src=\"/?ns=test&slot=${i}&sim=1\" title=\"טלפון ${i}\"></iframe></div></div>`;\n d.querySelector('button').onclick=()=>{const f=d.querySelector('iframe');f.src=f.src;};\n ph.appendChild(d);\n}\nfunction fit(){const c=ph.querySelector('.ph');if(!c)return;const r=c.getBoundingClientRect();const vh=ph.clientHeight-28,fitAll=$('#fit').checked;const s=Math.min(1,(r.width-6)/390,fitAll?(vh/2-26)/800:9);document.querySelectorAll('.hold').forEach(h=>{h.style.width=390*s+'px';h.style.height=800*s+'px';h.firstChild.style.transform=`scale(${s})`;});}\naddEventListener('resize',fit);$('#fit').onchange=fit;setTimeout(fit,50);\n$('#reload').onclick=()=>document.querySelectorAll('iframe').forEach(f=>f.src=f.src);\nlet resetArm=0;\n$('#reset').onclick=async()=>{\n const btn=$('#reset');\n if(Date.now()-resetArm>4000){resetArm=Date.now();btn.textContent='לחצו שוב למחיקת הכל';setTimeout(()=>{btn.textContent='איפוס סביבת הבדיקה';},4000);return;}\n resetArm=0;btn.textContent='איפוס סביבת הבדיקה';\n await fetch('/api/reset?ns=test',{method:'POST'});\n Object.keys(localStorage).filter(k=>k.startsWith('tz_test_')).forEach(k=>localStorage.removeItem(k));\n document.querySelectorAll('iframe').forEach(f=>f.src=f.src);poll();\n};\nfunction esc(t){const s=document.createElement('span');s.textContent=t==null?'':t;return s.innerHTML;}\nasync function poll(){\n try{\n  const [f,l]=await Promise.all([fetch('/api/feed?ns=test').then(r=>r.json()),fetch('/api/leaders?ns=test').then(r=>r.json())]);\n  const tot=f.stats.reduce((a,s)=>a+s.n,0),ok=f.stats.reduce((a,s)=>a+(s.ok||0),0);\n  $('#sOpen').textContent=f.open;$('#sTries').textContent=tot;$('#sRate').textContent=tot?Math.round(ok/tot*100)+'%':'–';\n  $('#lv').innerHTML=[1,2,3].map(k=>{const s=f.stats.find(x=>x.lvl===k)||{n:0,ok:0};const r=s.n?s.ok/s.n:0;\n   return `<div class=\"lvRow lv${k}\"><span class=\"nm\">${LV[k]}</span><span class=\"tr\"><span class=\"fl\" style=\"display:block;width:${r*100}%\"></span></span><span class=\"v num\">${s.n?`${s.ok}/${s.n} · ביטחון ${s.conf?Math.round(s.conf*100):0}%`:'אין עדיין'}</span></div>`;}).join('');\n  $('#lb').innerHTML=l.leaders.length?l.leaders.map((p,i)=>`<div class=\"lr\"><i class=\"num\">${i+1}</i><span>${p.bot?'🤖 ':''}${esc(p.name)} <small>· ${p.words} מילים</small></span><b class=\"num\">${p.score}</b></div>`).join(''):'<div class=\"empty\">צרו שחקנים בטלפונים</div>';\n  $('#feed').innerHTML=f.feed.length?f.feed.map(a=>`<div class=\"fr lv${a.lvl} ${a.ok?'ok':'no'}\"><span class=\"p num\"><bdi dir=\"ltr\">${a.points>0?\"+\":\"\"}${a.points}</bdi></span>${a.dbot?'🤖 ':''}${esc(a.drawer)} צייר <b class=\"w\">${esc(a.word)}</b> למוח של ${a.obot?'🤖 ':''}${esc(a.owner)} (${a.k} מילים) – ${a.ok?`זוהה ב־${Math.round(a.conf*100)}%`:`נחשב ל\"${esc(a.guess||'כלום')}\"`}</div>`).join(''):'<div class=\"empty\">עוד אין ניסיונות</div>';\n }catch(e){}\n}\npoll();setInterval(poll,3000);\n</script>\n</body>\n</html>\n";
// צייר המוחות – Cloudflare Worker (D1 + Web Push)

const N = 28, IN = N * N;
const MIN_EX = 1, MAX_EX = 10, MIN_WORDS = 5;
const BASE = { 1: 10, 2: 20, 3: 30, 4: 10 };
const LVL = new Map();
for (const k of ['1', '2', '3']) for (const w of WORDS[k]) LVL.set(w, +k);
// מילה חופשית (לא מהמאגר, עברה סינון) = רמה 4, ניקוד כמו פשוטה
const lvlOf = w => LVL.get(w) || (wordProblem(w) ? 0 : 4);

/* ---- זיהוי משולב: הרשת + "הציור הכי דומה ששמרת" (משותף לאפליקציה ולשרת, מוזרק בבנייה) ---- */
const KNN_ANG = [-45, -30, -15, 15, 30, 45];
// הכנה: שחור־לבן, עובי קו אחיד, טשטוש, ונרמול (וקטור יחידה ממורכז) – כך שמכפלה = מתאם צורה
function knnPrep(d, S) {
  const n = S * S, f = 28 / S, b = new Uint8Array(n), t = new Uint8Array(n), o = new Float32Array(n), h = new Float32Array(n);
  for (let y = 0; y < 28; y++) for (let x = 0; x < 28; x++) if (d[y * 28 + x] >= 6) b[((y / f) | 0) * S + ((x / f) | 0)] = 1;
  if (S === 28) {
    for (let y = 0, i = 0; y < S; y++) for (let x = 0; x < S; x++, i++) t[i] = b[i] | (x > 0 ? b[i - 1] : 0) | (x < S - 1 ? b[i + 1] : 0);
    for (let y = 0, i = 0; y < S; y++) for (let x = 0; x < S; x++, i++) o[i] = t[i] | (y > 0 ? t[i - S] : 0) | (y < S - 1 ? t[i + S] : 0);
  } else for (let i = 0; i < n; i++) o[i] = b[i];
  for (let pass = 0; pass < (S === 28 ? 2 : 1); pass++) {
    for (let y = 0, i = 0; y < S; y++) for (let x = 0; x < S; x++, i++) { let s = o[i], c = 1; if (x > 0) { s += o[i - 1]; c++; } if (x < S - 1) { s += o[i + 1]; c++; } h[i] = s / c; }
    for (let y = 0, i = 0; y < S; y++) for (let x = 0; x < S; x++, i++) { let s = h[i], c = 1; if (y > 0) { s += h[i - S]; c++; } if (y < S - 1) { s += h[i + S]; c++; } o[i] = s / c; }
  }
  let m = 0; for (let i = 0; i < n; i++) m += o[i]; m /= n;
  let q = 0; for (let i = 0; i < n; i++) { o[i] -= m; q += o[i] * o[i]; }
  q = 1 / (Math.sqrt(q) + 1e-9); for (let i = 0; i < n; i++) o[i] *= q;
  return o;
}
function knnDot(a, b) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }
// דמיון לכל מילה = הדמיון לציור הכי דומה שלה. exs: [{c, d}] ; must: מילים שחייבים לחשב במדויק
function wordSims(d, exs, K, must) {
  const s1 = new Float32Array(K), q14 = knnPrep(d, 14);
  for (const e of exs) { const u = e.u14 || (e.u14 = knnPrep(e.d, 14)); const v = knnDot(q14, u); if (v > s1[e.c]) s1[e.c] = v; }
  const cand = new Set(must || []);
  [...s1].map((v, i) => [v, i]).sort((a, b) => b[0] - a[0]).slice(0, 6).forEach(x => cand.add(x[1]));
  const qs = [knnPrep(d, 28)].concat(KNN_ANG.map(a => knnPrep(tf8(d, a), 28)));
  const s = new Float32Array(K);
  for (const e of exs) {
    if (!cand.has(e.c)) continue;
    const u = e.u28 || (e.u28 = knnPrep(e.d, 28));
    for (const q of qs) { const v = knnDot(q, u); if (v > s[e.c]) s[e.c] = v; }
  }
  return s;
}
// שילוב: חצי מהרשת, חצי מהציור הכי דומה
function mixP(p, s) {
  const K = p.length, q = new Float32Array(K); let mx = 0, sum = 0;
  for (let i = 0; i < K; i++) if (s[i] > mx) mx = s[i];
  for (let i = 0; i < K; i++) { q[i] = s[i] > 0 ? Math.exp((s[i] - mx) / 0.04) : 0; sum += q[i]; }
  const P = new Float32Array(K);
  for (let i = 0; i < K; i++) P[i] = 0.5 * p[i] + 0.5 * (sum ? q[i] / sum : 1 / K);
  return P;
}
// המילה שנבחרת = זו עם ציון ההתאמה הכי גבוה (ביטחון × דמיון); אם הכל 0 – לפי הביטחון בלבד
function bestWord(P, s, lo, hi) {
  let b = -1, bv = 0, a = 0;
  for (let i = 0; i < P.length; i++) { const v = P[i] * Math.min(1, Math.max(0, (s[i] - lo) / (hi - lo))); if (v > bv) { bv = v; b = i; } if (P[i] > P[a]) a = i; }
  return b >= 0 ? b : a;
}

/* ---------- ניקוד ---------- */
function sizeBonus(k) { return Math.min(2, Math.max(0, (k - MIN_WORDS) * 0.05)); }
// מכפיל סיכון: ציור אחד = ×3, עשרה ציורים = ×1
function riskMult(n) { return Math.round((3 - (Math.min(MAX_EX, Math.max(1, n)) - 1) * 2 / 9) * 10) / 10; }
const CURSE_MULT = { mirror: 1.5 };
const curseMult = c => MODE === 'ink' ? 1 : (CURSE_MULT[c] || 1);
function scoreFor(lvl, k, conf, ok, n, curse, extra = 1) {
  const b = BASE[lvl] || 10, m = riskMult(n) * curseMult(curse);
  return ok ? Math.max(1, Math.round(b * (1 + sizeBonus(k)) * m * extra * conf)) : -Math.round(b / 2 * m);
}
function maxScore(lvl, k, n, curse) { return Math.round((BASE[lvl] || 10) * (1 + sizeBonus(k)) * riskMult(n) * curseMult(curse)); }
const CURSES = ['line', 'three', 'mirror', 'white', 'time', 'straight', 'flip', 'rotate', 'shaky', 'dots', 'fade', 'tiny', 'fat'];
/* דמיון: הציור מושווה לציורים שבעל המוח שמר למילה */
const SIM_OK = 0.8, SIM_LO = 0.66, SIM_HI = 0.95;
const SIM_TF = [-45, -30, -15, 0, 15, 30, 45]; // הטיה עד 45° לכל כיוון, בלי היפוכים
// אותו עובי קו לכולם: הופכים לשחור־לבן ומעבים ב־1 פיקסל, כך שמשווים רק צורה
function thickN(d){const b=new Float32Array(IN);for(let y=0;y<N;y++)for(let x=0;x<N;x++){let on=0;for(let a=-1;a<=1&&!on;a++)for(let c=-1;c<=1;c++){const yy=y+a,xx=x+c;if(yy>=0&&yy<N&&xx>=0&&xx<N&&d[yy*N+xx]>=6){on=1;break;}}b[y*N+x]=on?15:0;}return b;}
function prep(d){return blur2(thickN(d));}
function blur2(d) { let o = Float32Array.from(d); for (let pass = 0; pass < 2; pass++) { const n = new Float32Array(IN); for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) { let s = 0, c = 0; for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) { const yy = y + a, xx = x + b; if (yy < 0 || yy >= N || xx < 0 || xx >= N) continue; s += o[yy * N + xx]; c++; } n[y * N + x] = s / c; } o = n; } return o; }
// מתאם (פירסון): משווה צורה, לא רק כמות דיו במרכז
function cosSim(a,b){let ma=0,mb=0;const n=a.length;for(let i=0;i<n;i++){ma+=a[i];mb+=b[i];}ma/=n;mb/=n;let s=0,x=0,y=0;for(let i=0;i<n;i++){const u=a[i]-ma,v=b[i]-mb;s+=u*v;x+=u*u;y+=v*v;}return s/Math.sqrt(x*y+1e-9);}
// היפוכים וסיבובים: 4 סיבובים × עם/בלי מראה
// הטיה קלה בלבד: סיבוב בזווית (מעלות), בלי היפוכים
function tf8(d,deg){if(!deg)return d;const o=new d.constructor(d.length),r=deg*Math.PI/180,c=Math.cos(r),s=Math.sin(r),m=(N-1)/2,isI=!(d instanceof Float32Array);for(let y=0;y<N;y++)for(let x=0;x<N;x++){const u=c*(x-m)+s*(y-m)+m,v=-s*(x-m)+c*(y-m)+m,x0=Math.floor(u),y0=Math.floor(v),fx=u-x0,fy=v-y0;let val=0;for(const [dx,dy,w] of [[0,0,(1-fx)*(1-fy)],[1,0,fx*(1-fy)],[0,1,(1-fx)*fy],[1,1,fx*fy]]){const xx=x0+dx,yy=y0+dy;if(xx>=0&&xx<N&&yy>=0&&yy<N)val+=d[yy*N+xx]*w;}o[y*N+x]=isI?Math.round(val):val;}return o;}
function simTo(d, exs) { const bd = prep(d), eb = exs.map(prep); let m = 0; for (const k of SIM_TF) { const t = tf8(bd, k); for (const e of eb) m = Math.max(m, cosSim(t, e)); } return m; }
const simFactor = s => Math.min(1, Math.max(0, (s - SIM_LO) / (SIM_HI - SIM_LO)));
async function unzipEx(b) {
  if (!b) return [];
  if (b[0] === 'P') return JSON.parse(decodeURIComponent(escape(atob(b.slice(1)))));
  const s = atob(b.slice(1)), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i);
  const ds = new Blob([u]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
  return JSON.parse(await new Response(ds).text());
}

/* ---------- רשת עצבית (שיפוט) ---------- */
function b64ToF32(b) {
  const s = atob(b), u = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i);
  return new Float32Array(u.buffer);
}
function strToD(s) {
  const d = new Uint8Array(IN);
  for (let i = 0; i < IN; i++) d[i] = parseInt(s[i], 16) || 0;
  return d;
}
function forward(net, d) {
  const H = net.H, W1 = net.W1, h = new Float32Array(H);
  const nz = []; for (let i = 0; i < IN; i++) if (d[i]) nz.push(i);
  for (let j = 0; j < H; j++) {
    let s = net.b1[j]; const o = j * IN;
    for (const i of nz) s += W1[o + i] * (d[i] / 15);
    h[j] = s > 0 ? s : 0;
  }
  const K = net.W2.length, p = new Float32Array(K); let m = -1e9;
  for (let k = 0; k < K; k++) { let s = net.b2[k]; const w = net.W2[k]; for (let j = 0; j < H; j++) s += w[j] * h[j]; p[k] = s; if (s > m) m = s; }
  let sum = 0; for (let k = 0; k < K; k++) { p[k] = Math.exp(p[k] - m); sum += p[k]; }
  for (let k = 0; k < K; k++) p[k] /= sum;
  return p;
}
function decodeNet(json) {
  const o = JSON.parse(json);
  return { H: o.H, W1: b64ToF32(o.W1), b1: b64ToF32(o.b1), W2: o.W2.map(b64ToF32), b2: o.b2 };
}

/* ---------- עזרים ---------- */
const now = () => Date.now();
const uid = () => crypto.randomUUID();
function json(o, status = 200) {
  return new Response(JSON.stringify(o), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } });
}
const err = (msg, status = 400) => json({ error: msg }, status);
const MODE = /*__MODE__*/'ink';
const NS_PLAIN = false;
function nsOf(url) { const b = url.searchParams.get('ns') === 'test' ? 'test' : 'live'; return MODE === 'ink' ? 'ink' + b : b; }
// דיו: יחס בין אורך הקו של המצייר לאורך הקו בציורים של בעל המוח
const INK_MAX = 10, DEF_L = 3;
function inkMult(r) { return Math.round((1 + (INK_MAX - 1) * Math.min(1, Math.max(0, (1 - r) / 0.85))) * 10) / 10; }
function medL(rows) { const Ls = rows.map(a => +a[2]).filter(x => x > 0).sort((x, y) => x - y); return Ls.length ? Ls[Ls.length >> 1] : DEF_L; }
async function body(req) { try { return await req.json(); } catch { return {}; } }
async function auth(req, env, ns) {
  const t = (req.headers.get('authorization') || '').replace(/^Bearer\s+/i, '');
  if (!t) return null;
  return env.DB.prepare('SELECT id,name,code,score FROM players WHERE token=? AND ns=?').bind(t, ns).first();
}
function cleanName(n) { return String(n || '').replace(/\s+/g, ' ').trim().slice(0, 14); }
function b64url(buf) { let s = ''; for (const x of new Uint8Array(buf)) s += String.fromCharCode(x); return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }

/* ---------- Web Push (VAPID, בלי תוכן – ה-Service Worker מושך את ההודעה) ---------- */
async function vapidAuth(env, endpoint, origin) {
  const aud = new URL(endpoint).origin;
  const enc = s => b64url(new TextEncoder().encode(JSON.stringify(s)));
  const unsigned = enc({ typ: 'JWT', alg: 'ES256' }) + '.' + enc({ aud, exp: Math.floor(now() / 1000) + 12 * 3600, sub: origin });
  const key = await crypto.subtle.importKey('jwk', JSON.parse(env.VAPID_PRIVATE_JWK), { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, new TextEncoder().encode(unsigned));
  return `vapid t=${unsigned}.${b64url(sig)}, k=${env.VAPID_PUBLIC}`;
}
async function pushTo(env, playerId, origin) {
  if (!env.VAPID_PRIVATE_JWK || !env.VAPID_PUBLIC) return;
  const { results } = await env.DB.prepare('SELECT endpoint FROM push_subs WHERE player_id=?').bind(playerId).all();
  for (const r of results) {
    try {
      const res = await fetch(r.endpoint, { method: 'POST', headers: { TTL: '86400', Urgency: 'normal', Authorization: await vapidAuth(env, r.endpoint, origin) } });
      if (res.status === 404 || res.status === 410) await env.DB.prepare('DELETE FROM push_subs WHERE endpoint=?').bind(r.endpoint).run();
    } catch (e) { /* ממשיכים */ }
  }
}
async function note(env, ns, playerId, kind, text, points, ctx, origin) {
  const id = uid();
  await env.DB.prepare('INSERT INTO notes(id,ns,player_id,kind,text,points,created) VALUES(?,?,?,?,?,?,?)').bind(id, ns, playerId, kind, text, points, now()).run();
  ctx.waitUntil(pushTo(env, playerId, origin));
  return id;
}
/* הקלטות ציור: נוצרת אוטומטית בפעם הראשונה (בלי צורך לשנות את מסד הנתונים ידנית) */
let recsReady = false;
async function ensureRecs(DB) {
  if (recsReady) return;
  await DB.prepare('CREATE TABLE IF NOT EXISTS recs (attempt_id TEXT PRIMARY KEY, ns TEXT NOT NULL, note_id TEXT, rec TEXT, created INTEGER NOT NULL)').run();
  await DB.prepare('CREATE INDEX IF NOT EXISTS recs_note ON recs(note_id)').run();
  // אפשר לנסות שוב אחרי כישלון – מבטלים את ההגבלה של ניסיון אחד
  await DB.prepare('DROP INDEX IF EXISTS att_once').run();
  // ניקוד לא יורד מתחת ל־0
  await DB.prepare('UPDATE players SET score=0 WHERE score<0').run();
  await DB.prepare('CREATE INDEX IF NOT EXISTS att_cp ON attempts(challenge_id, player_id)').run();
  recsReady = true;
}

/* ---------- Service Worker ---------- */
const SW = `
self.addEventListener('install',e=>self.skipWaiting());
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('push',e=>{e.waitUntil((async()=>{
 const sub=await self.registration.pushManager.getSubscription();
 let notes=[];
 try{const r=await fetch('/api/push/notes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({endpoint:sub&&sub.endpoint})});notes=(await r.json()).notes||[];}catch(err){}
 if(!notes.length)notes=[{text:'יש תוצאה חדשה באתגר שלך',id:'x'}];
 for(const n of notes.slice(0,3))await self.registration.showNotification('צייר המוחות',{body:n.text,tag:n.id,icon:'/icon-192.png',badge:'/icon-192.png',lang:'he',dir:'rtl'});
})());});
self.addEventListener('notificationclick',e=>{e.notification.close();e.waitUntil((async()=>{
 const all=await self.clients.matchAll({type:'window',includeUncontrolled:true});
 for(const c of all){if('focus' in c)return c.focus();}
 return self.clients.openWindow('/');
})());});
`;

const ICON_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="112" fill="#FF5A36"/><path d="M256 118c-34-30-96-22-112 22-42 2-66 46-48 82-28 24-24 76 10 94-2 40 40 70 78 56 18 28 54 30 72 10 18 20 54 18 72-10 38 14 80-16 78-56 34-18 38-70 10-94 18-36-6-80-48-82-16-44-78-52-112-22z" fill="#FFF6EA" stroke="#1F2440" stroke-width="16" stroke-linejoin="round"/><path d="M256 132v262M200 190c20 8 30 26 26 48M312 190c-20 8-30 26-26 48M170 290c22-10 46-6 60 12M342 290c-22-10-46-6-60 12" fill="none" stroke="#1F2440" stroke-width="14" stroke-linecap="round"/><circle cx="196" cy="246" r="14" fill="#FF5A36"/><circle cx="316" cy="246" r="14" fill="#FF5A36"/><circle cx="256" cy="330" r="14" fill="#FF5A36"/></svg>`;

function manifest() {
  return JSON.stringify({
    name: 'צייר המוחות', short_name: 'צייר המוחות', lang: 'he', dir: 'rtl',
    description: 'מלמדים מוח מלאכותי לזהות ציורים ומאתגרים את המוחות של כולם',
    start_url: '/', scope: '/', display: 'standalone', orientation: 'portrait',
    background_color: '#FBF6EC', theme_color: '#FBF6EC',
    icons: [{ src: '/icon-192.png', sizes: '192x192', type: 'image/png' }, { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' }, { src: '/icon.svg', sizes: 'any', type: 'image/svg+xml' }]
  });
}

/* ---------- API ---------- */
async function api(req, env, ctx, url) {
  const ns = nsOf(url), p = url.pathname, m = req.method, DB = env.DB, origin = url.origin;

  if (p === '/api/words') return json(WORDS);
  if (p === '/api/vapid') return json({ key: env.VAPID_PUBLIC || null });

  if (p === '/api/register' && m === 'POST') {
    const name = cleanName((await body(req)).name);
    if (name.length < 2) return err('שם קצר מדי');
    if (await DB.prepare('SELECT 1 FROM players WHERE ns=? AND name=?').bind(ns, name).first()) return err('השם הזה תפוס – נסו שם אחר');
    const code = String(1000 + Math.floor(Math.random() * 9000)), token = uid() + uid();
    const id = uid();
    await DB.prepare('INSERT INTO players(id,ns,name,code,token,score,created) VALUES(?,?,?,?,?,0,?)').bind(id, ns, name, code, token, now()).run();
    return json({ id, name, code, token, score: 0 });
  }
  if (p === '/api/login' && m === 'POST') {
    const b = await body(req), name = cleanName(b.name);
    const r = await DB.prepare('SELECT id,name,code,token,score FROM players WHERE ns=? AND name=? AND code=?').bind(ns, name, String(b.code || '').trim()).first();
    if (!r) return err('השם או הקוד לא נכונים', 401);
    return json(r);
  }
  if (p === '/api/push/notes' && m === 'POST') {
    const b = await body(req);
    const s = b.endpoint && await DB.prepare('SELECT player_id FROM push_subs WHERE endpoint=?').bind(b.endpoint).first();
    if (!s) return json({ notes: [] });
    const { results } = await DB.prepare('SELECT id,text FROM notes WHERE player_id=? AND seen=0 ORDER BY created DESC LIMIT 3').bind(s.player_id).all();
    return json({ notes: results });
  }
  if (p === '/api/leaders') {
    const { results } = await DB.prepare(`SELECT p.id,p.name,p.score,(p.id LIKE 'bot_%') bot,COALESCE(b.ready_words,0) words FROM players p LEFT JOIN brains b ON b.player_id=p.id WHERE p.ns=? ORDER BY p.score DESC, p.created ASC LIMIT 30`).bind(ns).all();
    return json({ leaders: results });
  }
  if (p === '/api/feed') {
    const { results } = await DB.prepare(`SELECT a.word,a.lvl,a.ok,a.conf,a.points,a.k,a.guess,a.created,d.name drawer,o.name owner,(a.player_id LIKE 'bot_%') dbot,(a.owner_id LIKE 'bot_%') obot FROM attempts a JOIN players d ON d.id=a.player_id JOIN players o ON o.id=a.owner_id WHERE a.ns=? ORDER BY a.created DESC LIMIT 40`).bind(ns).all();
    const stats = await DB.prepare(`SELECT lvl, COUNT(*) n, SUM(ok) ok, AVG(CASE WHEN ok=1 THEN conf END) conf FROM attempts WHERE ns=? GROUP BY lvl`).bind(ns).all();
    const open = await DB.prepare(`SELECT COUNT(*) n FROM challenges WHERE ns=? AND status='open'`).bind(ns).first();
    return json({ feed: results, stats: stats.results, open: open.n });
  }
  if (p === '/api/bots/tick' && m === 'POST') {
    if (!ns.endsWith('test')) return err('רק בסביבת הבדיקה', 403);
    return json({ log: await botTick(env, ns, ctx, origin) });
  }
  if (p === '/api/reset' && m === 'POST') {
    if (!ns.endsWith('test')) return err('אפשר לאפס רק את סביבת הבדיקה', 403);
    await DB.batch([
      DB.prepare(`DELETE FROM brains WHERE ns=?`).bind(ns), DB.prepare(`DELETE FROM challenges WHERE ns=?`).bind(ns),
      DB.prepare(`DELETE FROM attempts WHERE ns=?`).bind(ns), DB.prepare(`DELETE FROM notes WHERE ns=?`).bind(ns),
      DB.prepare(`DELETE FROM push_subs WHERE ns=?`).bind(ns), DB.prepare(`DELETE FROM players WHERE ns=?`).bind(ns)]);
    try { await ensureRecs(DB); await DB.prepare(`DELETE FROM recs WHERE ns=?`).bind(ns).run(); } catch (e) { }
    return json({ ok: true });
  }

  /* ---- מכאן נדרשת התחברות ---- */
  const me = await auth(req, env, ns);
  if (!me) return err('צריך להתחבר מחדש', 401);

  if (p === '/api/me') {
    const rank = await DB.prepare('SELECT COUNT(*)+1 r FROM players WHERE ns=? AND score>?').bind(ns, me.score).first();
    const { results: notes } = await DB.prepare('SELECT id,kind,text,points,created FROM notes WHERE player_id=? AND seen=0 ORDER BY created ASC LIMIT 10').bind(me.id).all();
    return json({ me: { id: me.id, name: me.name, code: me.code, score: me.score, rank: rank.r }, notes });
  }
  if (p === '/api/notes') {
    await ensureRecs(DB);
    const { results } = await DB.prepare('SELECT n.id,n.kind,n.text,n.points,n.seen,n.created,r.attempt_id aid FROM notes n LEFT JOIN recs r ON r.note_id=n.id WHERE n.player_id=? ORDER BY n.created DESC LIMIT 30').bind(me.id).all();
    return json({ notes: results });
  }
  // ניהול: רק מנהל המשחק – מחיקת כל השחקנים שאינם רובוטים
  if (p === '/api/admin/purge') {
    if (!isAdmin(me)) return err('אין הרשאה', 403);
    const sel = `SELECT id FROM players WHERE ns=? AND id NOT LIKE 'bot_%' AND id<>?`;
    const { results } = await DB.prepare(`SELECT name FROM players WHERE ns=? AND id NOT LIKE 'bot_%' AND id<>? ORDER BY name`).bind(ns, me.id).all();
    if (m !== 'POST') return json({ names: results.map(r => r.name) });
    await ensureRecs(DB);
    await DB.batch([
      DB.prepare(`DELETE FROM notes WHERE player_id IN (${sel})`).bind(ns, me.id),
      DB.prepare(`DELETE FROM push_subs WHERE player_id IN (${sel})`).bind(ns, me.id),
      DB.prepare(`DELETE FROM brains WHERE player_id IN (${sel})`).bind(ns, me.id),
      DB.prepare(`DELETE FROM attempts WHERE player_id IN (${sel}) OR owner_id IN (${sel})`).bind(ns, me.id, ns, me.id),
      DB.prepare(`DELETE FROM challenges WHERE owner_id IN (${sel})`).bind(ns, me.id),
      DB.prepare(`DELETE FROM recs WHERE ns=? AND attempt_id NOT IN (SELECT id FROM attempts)`).bind(ns),
      DB.prepare(`DELETE FROM players WHERE ns=? AND id NOT LIKE 'bot_%' AND id<>?`).bind(ns, me.id)]);
    return json({ ok: true, deleted: results.length });
  }
  // רשימת הניסיונות על אתגר שלי
  if (p === '/api/recs') {
    const cid = url.searchParams.get('c') || '';
    const { results } = await DB.prepare(`SELECT a.id,a.ok,a.points,a.created,d.name drawer,(a.player_id LIKE 'bot_%') bot FROM attempts a JOIN players d ON d.id=a.player_id WHERE a.challenge_id=? AND a.owner_id=? ORDER BY a.created DESC LIMIT 50`).bind(cid, me.id).all();
    return json({ attempts: results });
  }
  // ניסיון אחד + הקלטת הציור
  const mRec = p.match(/^\/api\/rec\/([\w-]+)$/);
  if (mRec) {
    await ensureRecs(DB);
    const a = await DB.prepare(`SELECT a.id,a.word,a.lvl,a.ok,a.conf,a.guess,a.points,a.d,a.created,a.player_id,a.owner_id,d.name drawer,(a.player_id LIKE 'bot_%') bot,r.rec FROM attempts a JOIN players d ON d.id=a.player_id LEFT JOIN recs r ON r.attempt_id=a.id WHERE a.id=?`).bind(mRec[1]).first();
    if (!a || (a.owner_id !== me.id && a.player_id !== me.id)) return err('לא נמצא', 404);
    const { player_id, owner_id, ...rest } = a;
    const ow = await DB.prepare('SELECT name FROM players WHERE id=?').bind(owner_id).first();
    return json({ attempt: { ...rest, mine: player_id === me.id, owner: ow ? ow.name : '' } });
  }
  // הניסיונות שלי באתגר מסוים (כדי ללמוד מהכישלונות)
  if (p === '/api/mytries') {
    const { results } = await DB.prepare(`SELECT id,ok,conf,guess,points,d,created FROM attempts WHERE challenge_id=? AND player_id=? ORDER BY created ASC LIMIT 30`).bind(url.searchParams.get('c') || '', me.id).all();
    return json({ attempts: results });
  }
  if (p === '/api/notes/seen' && m === 'POST') {
    await DB.prepare('UPDATE notes SET seen=1 WHERE player_id=?').bind(me.id).run();
    return json({ ok: true });
  }
  if (p === '/api/push/sub' && m === 'POST') {
    const b = await body(req);
    if (!b.endpoint) return err('חסר מנוי');
    await DB.prepare('INSERT OR REPLACE INTO push_subs(endpoint,ns,player_id,created) VALUES(?,?,?,?)').bind(b.endpoint, ns, me.id, now()).run();
    return json({ ok: true });
  }

  if (p === '/api/brain' && m === 'GET') {
    const r = await DB.prepare('SELECT cats,net,ex,rounds,updated FROM brains WHERE player_id=?').bind(me.id).first();
    return json({ brain: r || null });
  }
  if (p === '/api/brain' && m === 'PUT') {
    const b = await body(req);
    if (!Array.isArray(b.cats)) return err('מוח לא תקין');
    const cats = b.cats.filter(c => lvlOf(c.w)).map(c => ({ w: c.w, n: Math.min(MAX_EX, Math.max(0, c.n | 0)) }));
    if (cats.length !== b.cats.length) return err('יש במוח מילה שלא מתאימה למשחק');
    if (b.net) { const o = JSON.parse(b.net); if (!o.W2 || o.W2.length !== cats.length) return err('הרשת לא תואמת למילים'); }
    const ready = cats.filter(c => c.n >= MIN_EX).length;
    await DB.prepare(`INSERT INTO brains(player_id,ns,cats,ready_words,net,ex,rounds,updated) VALUES(?,?,?,?,?,?,?,?)
      ON CONFLICT(player_id) DO UPDATE SET cats=excluded.cats,ready_words=excluded.ready_words,net=excluded.net,ex=excluded.ex,rounds=excluded.rounds,updated=excluded.updated`)
      .bind(me.id, ns, JSON.stringify(cats), ready, b.net || null, b.ex || null, b.rounds | 0, now()).run();
    // אתגר פתוח על מילה שנמחקה או נמחקה מהמוח – נסגר
    const { results: open } = await DB.prepare(`SELECT id,word FROM challenges WHERE owner_id=? AND status='open'`).bind(me.id).all();
    const okW = new Set(cats.filter(c => c.n >= MIN_EX).map(c => c.w));
    for (const c of open) if (!okW.has(c.word) || ready < MIN_WORDS)
      await DB.prepare(`UPDATE challenges SET status='closed',closed_at=? WHERE id=?`).bind(now(), c.id).run();
    return json({ ok: true, ready });
  }

  if (p === '/api/square') {
    const { results } = await DB.prepare(`SELECT c.id,c.word,c.lvl,c.tries,c.created,c.curse,o.name owner,(c.owner_id LIKE 'bot_%') bot,COALESCE(b.ready_words,0) k,b.cats,b.ex,(SELECT COUNT(*) FROM attempts a2 WHERE a2.challenge_id=c.id AND a2.player_id=?) my
      FROM challenges c JOIN players o ON o.id=c.owner_id LEFT JOIN brains b ON b.player_id=c.owner_id
      WHERE c.ns=? AND c.status='open' AND c.owner_id<>? AND NOT EXISTS (SELECT 1 FROM attempts a WHERE a.challenge_id=c.id AND a.player_id=? AND a.ok=1)
      ORDER BY c.created DESC LIMIT 60`).bind(me.id, ns, me.id, me.id).all();
    const exCache = new Map();
    const out = await Promise.all(results.map(async c => {
      const cats = c.cats ? JSON.parse(c.cats) : [], k = cats.findIndex(x => x.w === c.word), n = (cats[k] || { n: 1 }).n;
      const { cats: _c, ex, ...rest } = c;
      const min = maxScore(c.lvl, c.k, n, c.curse);
      let Lm = DEF_L;
      if (MODE === 'ink' && ex) { if (!exCache.has(ex)) exCache.set(ex, await unzipEx(ex)); Lm = medL(exCache.get(ex).filter(a => a[0] === k)); }
      return { ...rest, n, mult: riskMult(n), cmult: curseMult(c.curse), min, max: MODE === 'ink' ? min * INK_MAX : min, Lmed: Lm, inkMax: INK_MAX };
    }));
    return json({ challenges: out });
  }
  if (p === '/api/mine') {
    const { results } = await DB.prepare(`SELECT c.id,c.word,c.lvl,c.status,c.tries,c.created,c.curse,s.name solver,(SELECT COUNT(*) FROM attempts a WHERE a.challenge_id=c.id AND a.ok=1) solves FROM challenges c LEFT JOIN players s ON s.id=c.solved_by
      WHERE c.owner_id=? AND c.status<>'closed' ORDER BY c.status='open' DESC, c.created DESC LIMIT 60`).bind(me.id).all();
    return json({ challenges: results });
  }
  if (p === '/api/challenge' && m === 'POST') {
    const word = String((await body(req)).word || '');
    const lvl = lvlOf(word); if (!lvl) return err('המילה לא מתאימה למשחק');
    const br = await DB.prepare('SELECT cats,ready_words,net FROM brains WHERE player_id=?').bind(me.id).first();
    if (!br || !br.net) return err('קודם צריך לאמן את המוח');
    const rw = JSON.parse(br.cats).filter(c => c.n >= MIN_EX).length;
    if (rw !== br.ready_words) { br.ready_words = rw; await DB.prepare('UPDATE brains SET ready_words=? WHERE player_id=?').bind(rw, me.id).run(); }
    if (br.ready_words < MIN_WORDS) return err(`צריך לפחות ${MIN_WORDS} מילים עם ${MIN_EX} ציורים כל אחת`);
    const c = JSON.parse(br.cats).find(c => c.w === word);
    if (!c || c.n < MIN_EX) return err(`למילה צריך לפחות ${MIN_EX} ציורים`);
    if (await DB.prepare(`SELECT 1 FROM challenges WHERE owner_id=? AND word=? AND status='open'`).bind(me.id, word).first()) return err('המילה הזאת כבר באתגר');
    if (await DB.prepare(`SELECT 1 FROM attempts WHERE owner_id=? AND word=? AND ok=1 LIMIT 1`).bind(me.id, word).first()) return err('המילה הזאת כבר נפתרה – אי אפשר לפרסם אותה שוב');
    const id = uid();
    const curse = MODE === 'ink' ? null : CURSES[Math.floor(Math.random() * CURSES.length)];
    await DB.prepare('INSERT INTO challenges(id,ns,owner_id,word,lvl,status,tries,created,curse) VALUES(?,?,?,?,?,\'open\',0,?,?)').bind(id, ns, me.id, word, lvl, now(), curse).run();
    return json({ ok: true, id, curse });
  }
  const mDel = p.match(/^\/api\/challenge\/([\w-]+)$/);
  if (mDel && m === 'DELETE') {
    await DB.prepare(`UPDATE challenges SET status='closed',closed_at=? WHERE id=? AND owner_id=? AND status='open'`).bind(now(), mDel[1], me.id).run();
    return json({ ok: true });
  }

  if (p === '/api/attempt' && m === 'POST') {
    const b = await body(req);
    const c = await DB.prepare(`SELECT c.*,o.name owner FROM challenges c JOIN players o ON o.id=c.owner_id WHERE c.id=? AND c.ns=?`).bind(b.id, ns).first();
    if (!c) return err('האתגר לא נמצא', 404);
    const ds = typeof b.d === 'string' && /^[0-9a-f]{784}$/.test(b.d) ? b.d : null;
    const rec = typeof b.rec === 'string' && b.rec.length < 24000 && /^[A-Za-z0-9+/=]*$/.test(b.rec) ? b.rec : null;
    const r = await runAttempt(env, ns, me, c, ds, +b.L || 0, ctx, origin, rec);
    return r.error ? err(r.error) : json(r);
  }
  return err('לא נמצא', 404);
}


/* ---------- ניסיון אתגר (משותף לשחקנים ולרובוטים) ---------- */
const isBot = id => typeof id === 'string' && id.startsWith('bot_');
async function runAttempt(env, ns, me, c, ds, Lin, ctx, origin, rec = null) {
  const DB = env.DB;
  if (c.owner_id === me.id) return { error: 'אי אפשר לאתגר את המוח של עצמך' };
  if (c.status !== 'open') return { error: 'האתגר נסגר' };
  await ensureRecs(DB);
  if (await DB.prepare('SELECT 1 FROM attempts WHERE challenge_id=? AND player_id=? AND ok=1').bind(c.id, me.id).first()) return { error: 'כבר פתרת את האתגר הזה' };
  const br = await DB.prepare('SELECT cats,ready_words,net,ex FROM brains WHERE player_id=?').bind(c.owner_id).first();
  const cats = br ? JSON.parse(br.cats) : [];
  const k = cats.findIndex(x => x.w === c.word);
  if (!br || !br.net || k < 0) return { error: 'המוח של בעל האתגר השתנה – האתגר נסגר' };
  let ok = false, conf = 0, guess = '', sim = 0, prob = 0;
  const exEvery = await unzipEx(br.ex), exAll = exEvery.filter(a => a[0] === k), exK = exAll.map(a => strToD(a[1]));
  const Lmed = medL(exAll);
  const L = Math.max(0, Lin || 0), inkR = L ? L / Lmed : 1, im = MODE === 'ink' ? inkMult(inkR) : 1;
  const nEx = Math.max(1, exK.length || cats[k].n);
  if (ds) {
    const d = strToD(ds), p2 = forward(decodeNet(br.net), d);
    // זיהוי משולב: הרשת + הציור הכי דומה ששמר בעל המוח
    let P = p2, sv = null;
    if (exK.length) {
      const topP = [...p2].map((v, i) => [v, i]).sort((a, b) => b[0] - a[0]).slice(0, 6).map(x => x[1]);
      sv = wordSims(d, exEvery.map(a => ({ c: a[0], d: strToD(a[1]) })), p2.length, [k, ...topP]); P = mixP(p2, sv);
    }
    let g = 0; if (sv) g = bestWord(P, sv, SIM_LO, SIM_HI); else for (let i = 1; i < P.length; i++) if (P[i] > P[g]) g = i;
    sim = sv ? sv[k] : 1; prob = P[k];
    ok = g === k && sim >= SIM_OK; conf = prob * simFactor(sim); guess = g === k && !ok ? '' : cats[g].w;
  }
  const K = cats.filter(x => x.n >= MIN_EX).length, pts = scoreFor(c.lvl, K, conf, ok, nEx, c.curse, im);
  // כישלון מוריד נקודות רק למי שמצייר; בעל המוח לא מפסיד
  const ownerPts = ok ? pts : 0;
  // האתגר נשאר פתוח גם אחרי הצלחה (נעלם רק אצל מי שפתר). solved_by = הפותר האחרון
  if (ok) await DB.prepare('UPDATE challenges SET tries=tries+1,solved_by=? WHERE id=?').bind(me.id, c.id).run();
  else await DB.prepare('UPDATE challenges SET tries=tries+1 WHERE id=?').bind(c.id).run();
  // אתגר של רובוט נסגר אחרי 3 פותרים, כדי שיתחלפו אתגרים
  if (ok && isBot(c.owner_id)) { const sv = await DB.prepare('SELECT COUNT(*) n FROM attempts WHERE challenge_id=? AND ok=1').bind(c.id).first(); if (sv.n >= 2) await DB.prepare(`UPDATE challenges SET status='closed',closed_at=? WHERE id=?`).bind(now(), c.id).run(); }
  const aid = uid();
  await DB.batch([
    DB.prepare('INSERT INTO attempts(id,ns,challenge_id,player_id,owner_id,word,lvl,ok,conf,guess,points,k,d,created) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
      .bind(aid, ns, c.id, me.id, c.owner_id, c.word, c.lvl, ok ? 1 : 0, conf, guess, pts, K, ds, now()),
    DB.prepare('UPDATE players SET score=MAX(0,score+?) WHERE id=?').bind(pts, me.id),
    DB.prepare('UPDATE players SET score=MAX(0,score+?) WHERE id=?').bind(ownerPts, c.owner_id)]);
  const pc = Math.round(conf * 100);
  const gain = v => v > 0 ? `קיבלת ${v} נקודות` : v < 0 ? `איבדת ${-v} נקודות` : 'לא הפסדת נקודות';
  const who = isBot(me.id) ? `🤖 ${me.name}` : me.name;
  let nid = null;
  if (!isBot(c.owner_id)) nid = await note(env, ns, c.owner_id, ok ? 'win' : 'lose', ok
    ? `${who} צייר "${c.word}" – המוח שלך זיהה ב־${pc}%. ${gain(ownerPts)}`
    : guess ? `${who} צייר "${c.word}" – המוח שלך חשב שזה "${guess}". ${gain(ownerPts)}` : `${who} צייר "${c.word}" – לא דומה מספיק לציורים שלך. ${gain(ownerPts)}`, ownerPts, ctx, origin);
  if (!isBot(me.id) || !isBot(c.owner_id)) if (rec || ds) { try { await ensureRecs(DB); await DB.prepare('INSERT INTO recs(attempt_id,ns,note_id,rec,created) VALUES(?,?,?,?,?)').bind(aid, ns, nid, rec, now()).run(); } catch (e) { } }
  if (!isBot(me.id)) await note(env, ns, me.id, ok ? 'dwin' : 'dlose', ok
    ? `המוח של ${c.owner} זיהה את "${c.word}" שלך ב־${pc}%. ${gain(pts)}`
    : `המוח של ${c.owner} לא זיהה את "${c.word}" שלך. ${gain(pts)}`, pts, ctx, origin);
  return { ok, conf, guess, sim, prob, n: nEx, mult: riskMult(nEx), cmult: curseMult(c.curse), imult: im, inkR, mode: MODE, points: pts, k: K, lvl: c.lvl, word: c.word, owner: c.owner, ownerBot: isBot(c.owner_id), empty: !ds };
}

/* ---------- שחקני מחשב ---------- */
// מנהל המשחק: מזוהה לפי הקוד האישי (לא לפי איות השם)
const isAdmin = me => !me.id.startsWith('bot_') && String(me.code) === '6351' && me.name.startsWith('ארנ');
const BOT_MAX_OPEN = 2, BOT_TOTAL_OPEN = 14;
function b64f32(b) { return b64ToF32(b); }
function f32b64(a) { const u = new Uint8Array(a.buffer, a.byteOffset, a.byteLength); let s = ''; for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode.apply(null, u.subarray(i, i + 0x8000)); return btoa(s); }
function botNet(n) {
  const s = atob(n.q), sc = b64f32(n.s), W1 = new Float32Array(64 * IN);
  for (let j = 0; j < 64; j++) for (let i = 0; i < IN; i++) { let v = s.charCodeAt(j * IN + i); if (v > 127) v -= 256; W1[j * IN + i] = v * sc[j]; }
  return JSON.stringify({ H: 64, W1: f32b64(W1), b1: n.b1, W2: n.W2, b2: n.b2 });
}
async function ensureBots(env, ns) {
  const DB = env.DB;
  const have = await DB.prepare(`SELECT COUNT(*) n FROM players WHERE ns=? AND id LIKE 'bot_%'`).bind(ns).first();
  if (have.n >= BOTS.bots.length) {
    // מוחות רובוטים מגרסה ישנה – מוחלפים במוח המאומן החדש (2 בכל פעם). rounds = מספר הגרסה
    const ver = BOTS.ver || 1;
    const { results: old } = await DB.prepare(`SELECT player_id FROM brains WHERE ns=? AND player_id LIKE 'bot_%' AND rounds<? LIMIT 2`).bind(ns, ver).all();
    for (const o of old) {
      const i = +o.player_id.split('_').pop(), bt = BOTS.bots[i]; if (!bt) continue;
      await DB.prepare('UPDATE brains SET cats=?,ready_words=?,net=?,ex=?,rounds=?,updated=? WHERE player_id=?')
        .bind(JSON.stringify(bt.cats), bt.cats.length, botNet(bt.net), bt.ex, ver, now(), o.player_id).run();
    }
    return;
  }
  let added = 0; // מעט בכל פעם – כדי לא לחרוג מזמן החישוב
  for (let i = 0; i < BOTS.bots.length && added < 2; i++) {
    const bt = BOTS.bots[i], id = `bot_${ns}_${i}`;
    if (await DB.prepare('SELECT 1 FROM players WHERE id=?').bind(id).first()) continue;
    added++;
    let name = bt.name;
    if (await DB.prepare('SELECT 1 FROM players WHERE ns=? AND name=?').bind(ns, name).first()) name = name + ' ' + (i + 2);
    await DB.prepare('INSERT INTO players(id,ns,name,code,token,score,created) VALUES(?,?,?,?,?,0,?)').bind(id, ns, name, 'bot-' + uid(), 'bot-' + uid() + uid(), now()).run();
    await DB.prepare('INSERT OR REPLACE INTO brains(player_id,ns,cats,ready_words,net,ex,rounds,updated) VALUES(?,?,?,?,?,?,?,?)')
      .bind(id, ns, JSON.stringify(bt.cats), bt.cats.length, botNet(bt.net), bt.ex, BOTS.ver || 1, now()).run();
  }
}
function poolDrawing(word) {
  const p = BOTS.pool[word]; if (!p) return null;
  const n = p.L.length, i = Math.floor(Math.random() * n);
  let hex = '';
  if (p.b2) { // 2 ביט לנקודה (קו נקי ומוחלק)
    const s = atob(p.b2);
    for (let q = 0; q < IN; q++) { const bit = (i * IN + q) * 2, byte = s.charCodeAt(bit >> 3), v = (byte >> (6 - (bit & 7))) & 3; hex += '05af'[v]; }
  } else { const s = atob(p.b); for (let q = 0; q < IN; q++) { const byte = s.charCodeAt(i * 98 + (q >> 3)); hex += (byte >> (7 - (q & 7))) & 1 ? 'f' : '0'; } }
  return { d: hex, L: p.L[i] };
}
// ציור ממה שלמדו מהשחקנים האמיתיים: ציורים ששמרו במוח שלהם או שזוהו באתגרים
async function learnedDrawing(env, ns, word, ownerId) {
  const DB = env.DB;
  const a = await DB.prepare(`SELECT d FROM attempts WHERE ns=? AND word=? AND ok=1 AND d IS NOT NULL AND player_id NOT LIKE 'bot_%' AND owner_id<>? ORDER BY RANDOM() LIMIT 1`).bind(ns, word, ownerId).first();
  const fromBrains = await DB.prepare(`SELECT cats,ex FROM brains WHERE ns=? AND player_id NOT LIKE 'bot_%' AND player_id<>? AND cats LIKE ? ORDER BY RANDOM() LIMIT 1`).bind(ns, ownerId, `%"w":"${word}"%`).first();
  const opts = [];
  if (a) opts.push({ d: a.d, L: 0 });
  if (fromBrains) {
    const k = JSON.parse(fromBrains.cats).findIndex(x => x.w === word);
    const ex = (await unzipEx(fromBrains.ex)).filter(e => e[0] === k);
    if (ex.length) { const e = ex[Math.floor(Math.random() * ex.length)]; opts.push({ d: e[1], L: e[2] || 0 }); }
  }
  return opts.length ? opts[Math.floor(Math.random() * opts.length)] : null;
}
async function botTick(env, ns, ctx, origin) {
  const DB = env.DB;
  await ensureBots(env, ns);
  const log = [];
  // 1. ניסיון אתגר
  const { results: open } = await DB.prepare(`SELECT c.*,o.name owner FROM challenges c JOIN players o ON o.id=c.owner_id WHERE c.ns=? AND c.status='open' ORDER BY RANDOM() LIMIT 20`).bind(ns).all();
  const humanFirst = open.sort((x, y) => (isBot(x.owner_id) ? 1 : 0) - (isBot(y.owner_id) ? 1 : 0) + (Math.random() - .5));
  for (const c of humanFirst.slice(0, 3)) {
    const { results: tried } = await DB.prepare('SELECT player_id FROM attempts WHERE challenge_id=?').bind(c.id).all();
    const triedSet = new Set(tried.map(t => t.player_id));
    const cand = BOTS.bots.map((_, i) => `bot_${ns}_${i}`).filter(id => id !== c.owner_id && !triedSet.has(id));
    if (!cand.length) continue;
    const id = cand[Math.floor(Math.random() * cand.length)];
    const me = await DB.prepare('SELECT id,name FROM players WHERE id=?').bind(id).first(); if (!me) continue;
    const dr = poolDrawing(c.word) || await learnedDrawing(env, ns, c.word, c.owner_id);
    if (!dr) { log.push(`אין ציור ל"${c.word}"`); continue; }
    const r = await runAttempt(env, ns, me, c, dr.d, dr.L, ctx, origin);
    log.push(`${me.name} → "${c.word}" של ${c.owner}: ${r.error || (r.ok ? 'זוהה' : 'לא זוהה') + ' ' + (r.points ?? '')}`);
    break;
  }
  // 2. פרסום אתגר
  const tot = await DB.prepare(`SELECT COUNT(*) n FROM challenges WHERE ns=? AND status='open' AND owner_id LIKE 'bot_%'`).bind(ns).first();
  if (tot.n < BOT_TOTAL_OPEN && Math.random() < 0.6) {
    const i = Math.floor(Math.random() * BOTS.bots.length), id = `bot_${ns}_${i}`;
    const mine = await DB.prepare(`SELECT word,status FROM challenges WHERE owner_id=? AND status<>'closed'`).bind(id).all();
    const openN = mine.results.filter(x => x.status === 'open').length, used = new Set(mine.results.map(x => x.word));
    const free = BOTS.bots[i].cats.map(x => x.w).filter(w => !used.has(w));
    const seeded = await DB.prepare('SELECT 1 FROM brains WHERE player_id=?').bind(id).first();
    if (seeded && openN < BOT_MAX_OPEN && free.length) {
      const word = free[Math.floor(Math.random() * free.length)];
      await DB.prepare('INSERT INTO challenges(id,ns,owner_id,word,lvl,status,tries,created) VALUES(?,?,?,?,?,\'open\',0,?)').bind(uid(), ns, id, word, LVL.get(word), now()).run();
      log.push(`${BOTS.bots[i].name} פרסם "${word}"`);
    }
  }
  return log;
}

/* ---------- ניתוב ---------- */
export default {
  async scheduled(event, env, ctx) {
    const origin = 'https://tzayar-hamochot.contactarnon.workers.dev';
    const base = MODE === 'ink' && !NS_PLAIN ? 'ink' : '';
    try { await botTick(env, base + 'live', ctx, origin); } catch (e) { console.log('bots', e && e.message); }
    try { const t = await env.DB.prepare(`SELECT 1 FROM players WHERE ns=? AND id NOT LIKE 'bot_%' LIMIT 1`).bind(base + 'test').first(); if (t) await botTick(env, base + 'test', ctx, origin); } catch (e) { }
  },
  async fetch(req, env, ctx) {
    const url = new URL(req.url), p = url.pathname;
    try {
      if (p.startsWith('/api/')) return await api(req, env, ctx, url);
      if (p === '/' || p === '/index.html')
        return new Response(APP.replace('/*__WORDS__*/null', JSON.stringify(WORDS)).replace('/*__FILTER__*/null', () => JSON.stringify(WFILTER)).replace(/__ORIGIN__/g, url.origin), { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' } });
      if (p === '/sim') return new Response(SIM, { headers: { 'content-type': 'text/html; charset=utf-8', 'x-robots-tag': 'noindex' } });
      if (p === '/sw.js') return new Response(SW, { headers: { 'content-type': 'text/javascript; charset=utf-8', 'cache-control': 'no-cache' } });
      if (p === '/manifest.webmanifest') return new Response(manifest(), { headers: { 'content-type': 'application/manifest+json' } });
      if (p === '/icon.svg') return new Response(ICON_SVG, { headers: { 'content-type': 'image/svg+xml', 'cache-control': 'public, max-age=86400' } });
      if (p === '/icon-192.png' || p === '/icon-512.png' || p === '/apple-touch-icon.png') {
        const b = ICONS[p];
        if (b) { const s = atob(b), u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return new Response(u, { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=86400' } }); }
        return new Response(ICON_SVG, { headers: { 'content-type': 'image/svg+xml' } });
      }
      if (p === '/robots.txt') return new Response(`User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /sim\nSitemap: ${url.origin}/sitemap.xml\n`, { headers: { 'content-type': 'text/plain' } });
      if (p === '/sitemap.xml') return new Response(`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>${url.origin}/</loc><changefreq>weekly</changefreq></url></urlset>`, { headers: { 'content-type': 'application/xml' } });
      return new Response('לא נמצא', { status: 404 });
    } catch (e) {
      return err('שגיאת שרת: ' + (e && e.message || e), 500);
    }
  }
};
